import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAT: [CaseTemplate] = [parkSwingDamage, guitarPawned, handicapPlacardForge, poolAfterHours, fireworksStreet, usedCarScam, pickupLineSpeeding, rifleAtKids, textbookTheft, golfCartDwi, giftCardSwap, churchTreasurerSkim, liquorStoreHoldup, bakeryRearBreakin, packagedMarijuana, neighborStalking, nursingAideNeglect, roommateStabbing, ambushAtHome, armedConvenienceRobbery, fairgroundRiot]

    static let parkSwingDamage = SmallCases.make(
        key: "story.parkSwingDamage",
        category: .property,
        headlines: ["Swing Set and Bench Wrecked at Neighborhood Park", "Chains Cut and Seats Burned, Parks Department Says"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a town park, causing damage of $2,800, on {DATE}.",
        ages: 18...24,
        victim: true,
        summary: "A swing set and two benches at a town park were cut and burned overnight on {DATE}. A neighbor saw three teens leave around 1 a.m. A lighter and a hacksaw were found near the lot. {D}'s fingerprints were on the hacksaw. {DL} says {D.he} found it in the park the week before.",
        state: [E(.forensic, 3, "Fingerprints", "{D}'s prints on a hacksaw."), E(.statement, 2, "Neighbor", "Three teens leave around 1 a.m.")],
        defense: [E(.statement, 1, "Found Tool", "{DL} says {D.he} found the hacksaw the week before.")],
        role: "Parks department supervisor",
        exam: [.direct("What damage did you find at the park?", "\"The swing chains had been cut through and two benches were burned. Our crew found it at opening, and I walked the whole site.\""), .direct("What did the repairs cost?", "\"The total was $2,800 for new swing equipment and replacement benches, plus the labor to clear the burned area.\""), .direct("What was found near the parking lot?", "\"A hacksaw and a lighter lay near the lot. The forensic unit lifted fingerprints from the hacksaw, and they were {D}'s.\""), .direct("Walk the jury through the damage you saw at 7 a.m.", "\"The swing set chains were cut through and the seats lay on the ground. Two benches had burn marks across the slats, and the plastic slide had melted along one edge.\""), .direct("How did you find the hacksaw and the lighter?", "\"A crew member found them in the grass near the parking lot while walking the perimeter. We called deputies and left them where they lay until they arrived.\""), .direct("What connected {D} to the saw?", "\"Deputies lifted fingerprints from the handle and the lab matched them to {D}. That was the only physical link that was reported to me.\""), .cross("Prints can come from simply handling a tool, can't they?", "\"Yes. A fingerprint shows someone touched the saw, but it does not say when or why it was touched.\""), .cross("The neighbor couldn't identify any of the teens, could the neighbor?", "\"No. The neighbor saw three teens leave around one in the morning, but could not say who they were.\""), .cross("Is the park open to the public during the day?", "\"Yes, the park is public, and tools or trash can be left there by anyone. I can't say when the hacksaw was left.\""), .cross("How many people use the park on a weekend?", "\"Dozens. The park is open from dawn to dusk, and a lot of teenagers hang out there in the evening.\""), .cross("Did anyone see {D} at the park the night of the damage?", "\"The neighbor said three teens left at about one in the morning, but could not describe any of them well enough to name them.\"")],
        theory: ("{D} cut and burned park equipment.", "A found hacksaw."),
        allocution: "\"It was stupid. I'll pay.\"",
        truths: ("A lighter bearing {DL}'s initials was found nearby.", "A teen from another group later admitted burning the equipment."),
        defendant: [.direct("Were you at the park that night?", "\"No. I was not there. I was not part of any group that went there and did not damage anything.\""), .direct("How did your fingerprints get on the hacksaw?", "\"I found the hacksaw in the park the week before and picked it up to look at it. I set it back down afterward.\""), .direct("Tell the jury about the hacksaw.", "\"I found it lying near a bench at the park about a week before. I picked it up, looked at it, and set it back down because I figured someone would come for it.\""), .direct("Why did you mention the park to your friends?", "\"It was a joke. We were talking about how nothing ever happens in this town, and I said somebody ought to burn the playground down.\""), .direct("Where were you the night the equipment was damaged?", "\"At home. I live with my parents and I was in my room playing a game online until about one.\""), .direct("What did you do with the hacksaw after you found it in the park?", "\"I put it in my backpack and carried it around for a few days. I meant to ask around about who owned it, and I never got to it.\""), .cross("Your fingerprints are on the tool used to cut the swing chains. Isn't that a problem?", "\"It looks like one, but I touched it before that night. I did not use it on any swing.\""), .cross("A lighter with your initials was found near the lot. Can you explain that?", "\"It is mine, and I lost it. I do not know how it ended up by the lot.\""), .cross("You were bragging about the park to your friends, weren't you?", "\"It was a joke. I said some dumb things, but I did not do it.\""), .cross("A lighter with your initials was found near the lot. How do you explain it?", "\"I lost a lighter around then. I don't know where it fell, and I never saw it again before deputies showed it to me.\""), .cross("You told friends the park should be burned and then it was. Isn't that a coincidence?", "\"I said something stupid in a group chat. I didn't mean it, and I'd never do something like that.\"")],
        openings: ("A swing set and two benches at a town park were cut and burned overnight, costing $2,800 to repair. A neighbor saw three teens leave at 1 a.m., and {D}'s fingerprints are on the hacksaw left behind.", "{D} found that hacksaw in the park a week earlier and was not there that night. The defense will show a neighbor who identified no one and prints that show a touch, not a crime."),
        closings: ("A hacksaw at the scene, {D}'s fingerprints on it, and a lighter with {D}'s initials nearby. Three teens left at one in the morning, and the evidence says {D} was one of them.", "A fingerprint shows only that someone touched a tool. {D} found it days earlier, and the neighbor identified no one. The State has pieces, but it has not put {D} at that park."),
        timeline: [(0, "12:40 a.m.: three teens enter the park."), (0, "1 a.m.: they leave."), (0, "7 a.m.: parks staff find the damage.")],
        identified: "Fingerprints and a lighter.",
        mood: .indifferent)

    static let guitarPawned = SmallCases.make(
        key: "story.guitarPawned",
        category: .property,
        headlines: ["Roommate's Prized Guitar Pawned While He Was on Tour", "Pawn Ticket Names Roommate"],
        law: "possStolen",
        spec: "Possessed a guitar valued at $1,800 belonging to {V}, knowing it to be stolen, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "{V} came home from a week away on {DATE} to find a guitar gone from {V.his} room. A pawn shop had taken in the same model the day before from {D}, {V}'s roommate. The serial number matched. {DL} says {V} told {D.him} to sell it.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on a ticket for the guitar."), E(.document, 3, "Serial Number", "Matches {V}'s purchase receipt.")],
        defense: [E(.statement, 1, "Permission", "{DL} says {V} told {D.him} to sell it.")],
        role: "Roommate",
        exam: [.direct("What happened when you came home on {DATE}?", "\"I'd been away for a week. When I walked into my room, the guitar I keep on the stand by the window was gone.\""), .direct("What kind of guitar was it?", "\"An acoustic I bought a couple of years ago and saved up for. I have the purchase receipt with the serial number.\""), .direct("Who lives in the apartment with you?", "\"{D}, my roommate. {D} was the only other person with a key and was home while I was away.\""), .direct("How did you learn what happened to the guitar?", "\"I called pawn shops. One had taken the same model the day before I got back, from {D}, and the serial number matched my receipt.\""), .direct("How much did you value it?", "\"I paid about $600. I used it for gigs and lessons, so it was more than a keepsake to me.\""), .direct("What did {D} say when you asked?", "\"{D} said I had told {D.him} to sell it. I never said any such thing, and I was stunned.\""), .cross("Isn't it true you called {D} the day before leaving?", "\"I called to cover rent and a couple of chores. I don't remember anything about the guitar coming up.\""), .cross("Did you ever sell or lend instruments to {D} before?", "\"Once, I let {D} borrow a keyboard for a weekend. I got it back, and we never talked about selling.\""), .cross("Do you have a text or message about selling it?", "\"No. If there was such a conversation, I have nothing written down, and I don't recall it.\""), .cross("Did {D} hide the sale?", "\"The pawn shop used {D}'s real ID and name, so no. {D} didn't use a fake identity.\""), .cross("Did you have money trouble that week?", "\"I was short on rent, which was part of why I asked {D} to cover it. I can't say I'd have sold the guitar.\"")],
        theory: ("{D} pawned a roommate's guitar.", "Permission to sell."),
        allocution: "\"I needed rent money.\"",
        truths: ("{DL} had texted a friend 'he'll never notice.'", "A call log showed {V} phoning {DL} the day before leaving and telling {D.him} to sell the guitar."),
        defendant: [.direct("Why did you pawn the guitar?", "\"{V} told me to sell it. {V} called the day before leaving and said I could sell the guitar if I needed money for rent.\""), .direct("What exactly did {V} say?", "\"Something like, if you're short, go ahead and sell the guitar and we'll sort it out when I'm back.\""), .direct("Why did you use your real name?", "\"Because I thought I had permission. I walked in with my own ID, and I didn't try to hide anything.\""), .direct("Did you need money that week?", "\"Yes. I was behind on my share of the rent, and I was worried about the landlord.\""), .direct("What happened when {V} returned?", "\"{V} was angry, and I said {V} had told me to sell it. We argued, and {V} called the shop.\""), .direct("What would you do now?", "\"I'd buy the guitar back if I could, and I'd get anything like that in writing from now on.\""), .cross("You never texted {V} to confirm?", "\"No. I took the phone call as enough, and I regret not putting it in writing.\""), .cross("You texted a friend that {V} would never notice, didn't you?", "\"I sent something like that. I was talking loosely, and it doesn't mean I thought I was stealing.\""), .cross("Did {V} sell instruments before?", "\"Not that I know of. I understand that makes my story harder to believe.\""), .cross("Didn't you pawn it for much less than it was worth?", "\"I took the loan the shop offered. I wasn't trying to get full value, just enough for rent.\""), .cross("You didn't tell {V} when {V} came home?", "\"I told {V} right away. I didn't hide it, and I said what I thought was agreed.\"")],
        openings: ("{V} came home after a week away to find a guitar missing from {V.his} room. The pawn shop had taken that same model the day before from {D}, {V}'s roommate, and the serial number matches {V}'s receipt.", "{D} says {V} phoned the day before leaving and told {D.him} to sell the guitar if rent ran short. The defense says a roommate who uses a real ID and says so openly is not stealing."),
        closings: ("The guitar was {V}'s, the pawn ticket carries {D}'s name, and {D} had texted a friend that {V} would never notice. A person with permission has no reason to say that.", "The call log shows {V} phoned {D} the day before leaving, and {D} pawned the guitar under {D}'s own name. The State has not proved {D} meant to take something that was not {D}'s to sell."),
        timeline: [(-7, "{V} leaves for a week."), (-1, "{DL} pawns the guitar."), (0, "{V} returns to find it gone.")],
        identified: "A pawn ticket.",
        mood: .wantsConviction,
        impact: "That guitar was my dad's.",
        genders: ["V": .male])

    static let handicapPlacardForge = SmallCases.make(
        key: "story.handicapPlacardForge",
        category: .whiteCollar,
        headlines: ["Man Parks in Accessible Space With Altered Placard", "Parking Officer Notes Photocopied Permit"],
        law: "forgery",
        spec: "Falsely made an accessible parking placard with intent to defraud, on {DATE}.",
        ages: 24...65,
        victim: false,
        summary: "A parking officer noticed on {DATE} that a placard on {D}'s mirror had smudged print and a mismatched number. The state registry listed the number for a deceased permit holder. {DL} says {D.he} found the placard in a used car {D.he} bought.",
        state: [E(.physical, 3, "Placard", "A photocopied placard with a deceased holder's number.", .search), E(.document, 3, "Registry", "The permit number belongs to a deceased holder.")],
        defense: [E(.statement, 1, "Used Car", "{DL} says it came with the car.")],
        role: "Parking officer",
        exam: [.direct("What did you notice on {DATE}?", "\"I was patrolling a parking area and noticed a handicap placard hanging from the mirror of {D}'s car. The print looked smudged and uneven.\""), .direct("What made it look wrong?", "\"The text was blurry, the color was slightly off, and the number didn't line up with the format the state uses.\""), .direct("What did you do next?", "\"I wrote down the number and ran it through the state registry. The registry listed that number for a permit holder who is deceased.\""), .direct("What did you conclude?", "\"That the placard was a photocopy of a real one, and that no living person was authorized to use that number.\""), .direct("What did {D} say?", "\"{D} said it was in the car when {D} bought it about a month earlier and that {D} didn't know it was fake.\""), .direct("Did {D} have a disability?", "\"I didn't verify one. Whether {D} had a disability wasn't the point, because the placard itself wasn't valid.\""), .cross("Isn't it true you don't know who made the copy?", "\"That's right. I only know it was a copy of a real placard. I can't say who copied it or when.\""), .cross("Did {D} try to hide the placard?", "\"No. It hung openly from the mirror, where anyone walking past could see it.\""), .cross("Did {D} argue or leave?", "\"No. {D} was polite and surprised, and gave me the details about the used car without any trouble.\""), .cross("Did you check who the car's previous owner was?", "\"Not at the scene. That was left to a follow-up investigation, and I don't know what it found.\""), .cross("How easy is it to spot a copy?", "\"Not very, if you aren't looking. The smudged print was what caught my eye, and a casual passerby wouldn't notice.\"")],
        theory: ("{D} used a copied placard.", "A placard left in a used car."),
        allocution: "\"I used it. I'm sorry.\"",
        truths: ("A scanner and printer in {DL}'s office printed the same pattern.", "The car's former owner's family confirmed the placard was in the glove box when {DL} bought it."),
        defendant: [.direct("How did the placard come to be in your car?", "\"I bought the car used about a month before. The placard was in the glove box when I got it.\""), .direct("Why did you hang it on the mirror?", "\"I don't have a disability. I put it up one time because the lot was full and I figured it came with the car. That was a mistake.\""), .direct("Did you know it was a copy?", "\"No. It looked like a regular placard to me, and I didn't read the small print or check the number.\""), .direct("Do you own a scanner or printer?", "\"Yes, in my office. Lots of people have them, and I use them for work papers.\""), .direct("What did you do when the officer asked about it?", "\"I told the truth about the used car and handed over the placard. I wasn't hiding anything.\""), .direct("What would you change?", "\"I'd have taken it to the DMV the day I found it. I shouldn't have hung it up when it wasn't mine.\""), .cross("You hung a placard that wasn't issued to you?", "\"Yes. I knew it wasn't issued in my name, and I used it anyway.\""), .cross("A scanner in your office printed the same pattern, didn't it?", "\"I'm told that. It's an ordinary office machine, and I didn't make a copy of any placard.\""), .cross("Did you call the previous owner?", "\"No. I didn't think about it until the officer stopped me.\""), .cross("You bought the car thirty days before?", "\"About that long. I had it for a month and didn't think about the placard until I needed a space.\""), .cross("You never checked whether the placard was valid?", "\"No. I assumed it was good because it was in the car. I should have asked.\"")],
        openings: ("A parking officer saw a handicap placard on {D}'s mirror with smudged print and a number that did not match the state format. The registry showed that number belonged to a deceased permit holder, and the State will show it was a photocopy.", "{D} bought a used car and found the placard in the glove box. The defense says {D} never made a copy and did not know it was fake."),
        closings: ("Smudged print, a wrong number, and a registry that lists a deceased holder. {D} hung a copy on the mirror, and a scanner in {D}'s office printed the same pattern.", "The placard came with a used car, and the former owner's family confirmed it was in the glove box. {D} hung it in plain sight and answered every question, which is how an unaware driver behaves."),
        timeline: [(-30, "{DL} buys the car."), (0, "A parking officer notes the placard."), (0, "The registry check is run.")],
        identified: "The registry.",
        mood: .indifferent,
        genders: ["D": .male])

    static let poolAfterHours = SmallCases.make(
        key: "story.poolAfterHours",
        category: .property,
        headlines: ["Teens Swim in Closed Community Pool After Dark", "Security Camera Records Gate Climbed"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a community pool, after being notified not to, on {DATE}.",
        ages: 18...22,
        victim: true,
        summary: "A community pool closed at dusk on {DATE} with a posted notice. A security camera showed four teens climb the fence and swim until a deputy arrived. {D} was among those detained. {DL} says the gate was open.",
        state: [E(.video, 3, "Security Camera", "Four teens climb the fence at 10 p.m."), E(.document, 2, "Posted Notice", "A closing notice on the gate.")],
        defense: [E(.statement, 1, "Open Gate", "{DL} says the gate was open.")],
        role: "Pool manager",
        exam: [.direct("What do you manage at the pool, and was it open on the night in question?", "\"I manage the community pool. It closes at dusk, and on {DATE} it closed at 9:45 p.m. like it does every night in the off-season.\""), .direct("Was there any notice that the pool was closed after dark?", "\"Yes. There's a laminated notice zip-tied to the front gate that says the pool is closed at dusk and anyone on the premises after that is trespassing. I checked it that afternoon and it was still up.\""), .direct("What did you see when you reviewed the security camera?", "\"Four young people came up to the fence at about ten o'clock, climbed over near the filter shed, and were in the water within a couple of minutes. A deputy arrived about forty minutes later.\""), .direct("How many people can use the pool during a typical evening in summer?", "\"About fifty at a time. We keep two lifeguards on duty until closing, and the gates are locked by a staff member once the pool is empty.\""), .direct("What did you do after you reviewed the camera footage?", "\"I wrote down the time stamps, saved the file, and gave it to the deputy who responded. The deputy identified the four on the video.\""), .direct("What did you find at the pool the next morning?", "\"Wet towels and a couple of bottles on the deck, and a muddy shoe print by the diving board. Nothing was damaged or missing.\""), .cross("Isn't it true the side gate was found open when the deputy arrived?", "\"The deputy told me it was ajar when the deputy walked in, but the camera shows them climbing the fence, so I can't tell you why they thought they needed to.\""), .cross("When did you last check the latch on that gate?", "\"I check the locks on Fridays. It was Wednesday night, so it had been five days. I can't swear what condition the latch was in on the night itself.\""), .cross("Was anything damaged or taken from the pool that night?", "\"No. There was some water on the deck and a wet towel left behind, but nothing was broken and nothing was missing.\""), .cross("Did you check the side gate latch the day of the incident?", "\"I checked the front gate that afternoon. I can't say I looked at the side gate latch.\""), .cross("Did the deputy tell you how the four teens had entered?", "\"The deputy said they climbed the fence at the corner, which matches the camera. A couple of them said the side gate looked open.\"")],
        theory: ("{D} climbed into a closed pool.", "An open gate."),
        allocution: "\"Sorry. It was dumb.\"",
        truths: ("A cut was found on {DL}'s hand from the fence wire.", "The side gate latch was broken, per the maintenance log."),
        defendant: [.direct("Walk us through that night. Why were you at the pool?", "\"A few of us from school had been talking about it all week. It was hot, and it was somebody's idea to go for a swim after dark. I went along because I didn't want to be the one who said no.\""), .direct("How did you get onto the pool grounds?", "\"I thought the side gate was open. It was pushed in a little when we got there, and I figured that meant we could walk in. I didn't realize at first the others had already gone over the fence.\""), .direct("Did you see the closing notice on the gate?", "\"No. It was dark, we came up from the parking lot side, and I never went near the front gate. If I had read it, I wouldn't have gone in.\""), .direct("Who were the other three teens, and how did you know them?", "\"Classmates from school. We'd all been talking about it that week, and one of them said it would be fun to go for a swim at night.\""), .direct("What did you do once you were in the water?", "\"I swam a few laps and sat on the edge of the pool with my feet in. We kept the noise down and nobody was running or diving.\""), .direct("What happened when the deputy arrived?", "\"The deputy told us to get out and sit on the bench. We were polite and gave our names, and the deputy called our parents.\""), .cross("The State's exhibit shows a cut on your hand. Isn't that from the fence wire?", "\"I did cut it that night, but I don't know exactly on what. It could have been the fence or the gate hinge. I wasn't paying attention to it until later.\""), .cross("The camera shows you climbing, doesn't it?", "\"It shows somebody climbing. I'm not going to tell you it wasn't me. I went in through the gap by the filter shed at the end, after the others were already in the water.\""), .cross("You knew the pool was closed, didn't you?", "\"I knew it closed at some point in the evening. I didn't know it was closed that night and I didn't ask. That part was my mistake.\""), .cross("The notice on the gate said the pool closed at dusk. Isn't that a fair warning?", "\"If I'd seen it, yes. I didn't read it, and I should have paid more attention.\""), .cross("You knew the pool was closed. Why did you go in anyway?", "\"I knew it was closed for the day. I figured nobody would care, and I didn't think about the rules.\"")],
        openings: ("Members of the jury, the evidence is simple. A community pool closed at dusk with a notice on the gate. A security camera shows four young people climbing the fence after dark, and the State will show that {D} was one of them.", "Members of the jury, this case turns on one question: was the pool really closed to {D}? The defense will show a side gate with a broken latch, a young person who followed friends in, and no damage or theft of any kind."),
        closings: ("The pool was closed and the notice was posted. The camera shows the fence being climbed, a deputy found {D} inside, and a cut on {DL}'s hand matches the wire. Whatever the latch looked like, {D} entered after dark and stayed.", "The maintenance log shows the side gate latch was broken. {D} followed friends through an opening that looked like an invitation, never saw the notice, took nothing, and broke nothing. The State has not proved {D} knew the pool was closed."),
        timeline: [(0, "9:45 p.m.: the pool closes."), (0, "10 p.m.: four teens climb the fence."), (0, "10:40 p.m.: a deputy arrives.")],
        identified: "A security camera.",
        mood: .indifferent)

    static let fireworksStreet = SmallCases.make(
        key: "story.fireworksStreet",
        category: .publicOrder,
        headlines: ["Fireworks Set Off in Neighborhood Street at 1 A.M.", "Neighbors Report Explosions, Smoke on Cul-de-Sac"],
        law: "disorderly",
        spec: "Disturbed the peace by setting off fireworks in a public street, on {DATE}.",
        ages: 18...45,
        victim: false,
        summary: "Neighbors called deputies on {DATE} at 1 a.m. after repeated explosions on a cul-de-sac. A deputy found {D} with a box of fireworks and a burned patch of pavement. {DL} says {D.he} was celebrating a team win.",
        state: [E(.statement, 3, "Deputy", "{D} lit mortar shells in the street."), E(.video, 2, "Doorbell Camera", "Flashes and a figure in the street.")],
        defense: [E(.statement, 1, "Celebration", "{DL} says it was a celebration.")],
        role: "Sheriff's deputy",
        exam: [.direct("What call brought you to the cul-de-sac?", "\"Neighbors called at 1 a.m. on {DATE} reporting repeated explosions. They'd also called around 12:15 and been told to keep us posted.\""), .direct("What did you find when you arrived at 1:20?", "\"{D} standing in the street with a box of fireworks. There was a burned patch of pavement and a smell of smoke.\""), .direct("What kind of fireworks were they?", "\"Mortar shells, the kind that launch and burst overhead. They're loud and bright and can be dangerous in a residential street.\""), .direct("What did the neighbor's doorbell camera show?", "\"Flashes of light and a figure standing in the street. The sound is loud, and it shows several bursts.\""), .direct("What did {D} say?", "\"{D} said it was a celebration of a team win. {D} said {D.he} hadn't thought about the neighbors or the hour.\""), .direct("What did you do?", "\"I confiscated the remaining fireworks and cited {D} for the violations. {D} was cooperative and put the box down when I asked.\""), .cross("Isn't it true no one was injured?", "\"Correct. I didn't see an injury, and nobody reported one. There was some damage to the pavement.\""), .cross("Was there a permitted fireworks display that night?", "\"I understand the homeowners association had scheduled one. I didn't verify it that night and I don't know the time or place.\""), .cross("Did {D} try to run or hide?", "\"No. {D} was standing in the street with the box and stayed there until I arrived.\""), .cross("Did you see {D} light the mortars?", "\"I arrived after. The neighbors reported it, and the camera shows a figure, but I didn't see the lighting myself.\""), .cross("Did anyone say they were harmed?", "\"One neighbor said a dog ran off during the blasts. I didn't see the dog and can't say what happened.\"")],
        theory: ("{D} lit fireworks at night.", "A celebration."),
        allocution: "\"I'm sorry.\"",
        truths: ("A neighbor's dog ran into traffic during the blasts.", "The homeowners association had scheduled a permitted fireworks show that night."),
        defendant: [.direct("Why were you setting off fireworks?", "\"My team had just won a big game. A few of us were out in the street celebrating, and I got carried away.\""), .direct("Did you know about the hour?", "\"I knew it was late, but the energy was high. I wasn't thinking about the neighbors, and I should have been.\""), .direct("Where did the fireworks come from?", "\"I'd bought them for the holiday earlier and kept them in the garage. I brought them out for the win.\""), .direct("Did you hear anyone complain?", "\"A neighbor yelled something from a porch around midnight. I figured it was friendly noise, and I kept going.\""), .direct("What did you do when the deputy arrived?", "\"I stopped right away and put the box down. I apologized and answered every question.\""), .direct("What damage did you cause?", "\"A scorch mark on the pavement, which I scrubbed the next day. I also apologized to the neighbors.\""), .cross("You lit mortar shells in the middle of the street?", "\"Yes. I know that's not a safe place, and I didn't think it through.\""), .cross("It was one in the morning?", "\"About that, yes. I know it's too late for noise, and I wasn't thinking.\""), .cross("You were warned around 12:15, weren't you?", "\"A neighbor said something, and I took it as a joke. I should have stopped then.\""), .cross("A neighbor's dog ran into traffic?", "\"I heard that. I'm sorry for that and I hope the dog is okay.\""), .cross("Did you have a permit?", "\"No. I didn't think I needed one for a small celebration, and I know that was wrong.\"")],
        openings: ("At 1 a.m. neighbors on a cul-de-sac called deputies after repeated explosions. A deputy found {D} standing in the street with a box of mortar shells beside a burned patch of pavement, and a doorbell camera recorded the flashes.", "{D} was celebrating a team win with friends and meant no harm. The defense says a short burst of noise after a game is not the dangerous misuse of fireworks the State describes."),
        closings: ("Mortar shells at 1 a.m., a scorched street, neighbors who called twice, and a camera that recorded the bursts. {D} knew the hour and the risk, and went ahead anyway.", "This was a celebration that ran too late, with no injuries and a cooperative person who stopped when the deputy arrived. A neighborhood association had its own show that night, so noise was in the air."),
        timeline: [(0, "12:15 a.m.: the first warning."), (0, "1 a.m.: mortar shells."), (0, "1:20 a.m.: a deputy arrives.")],
        identified: "A deputy.",
        mood: .indifferent)

    static let usedCarScam = SmallCases.make(
        key: "story.usedCarScam",
        category: .whiteCollar,
        headlines: ["Seller Takes $4,500 for Car That Isn't His", "Buyer Says Title Was Never Delivered"],
        law: "falsePretenses",
        spec: "Obtained $4,500 from {V} by false pretenses, on {DATE}.",
        ages: 21...55,
        victim: true,
        summary: "{V} paid {D} $4,500 in cash for a used car on {DATE}. {D} said the title was at a lender and would be mailed. It never was. The car belonged to a relative who had not sold it. {DL} says the relative agreed to sell and later backed out.",
        state: [E(.document, 3, "Bill of Sale", "A handwritten bill of sale for $4,500."), E(.statement, 3, "Relative", "The relative never agreed to sell.")],
        defense: [E(.statement, 1, "Backed Out", "{DL} says the relative agreed and later backed out.")],
        role: "Buyer",
        exam: [.direct("How much did you pay for the car?", "\"$4,500 in cash. We wrote up a handwritten bill of sale, and I counted the money out in front of {D}.\""), .direct("What did {D} promise about the title?", "\"{D} said the title was at a lender and would come in the mail soon. I trusted that, and I took the car.\""), .direct("What happened with the title?", "\"It never came. I called {D} several times, and eventually I learned the car belonged to a relative who never agreed to sell it.\""), .direct("How did you find the car?", "\"An online listing for a gray sedan at $4,500. I called the number, and {D} said it was a family car being sold on behalf of a relative.\""), .direct("Describe the day you paid for it.", "\"I met {D} in a grocery store parking lot with $4,500 in cash. {D} wrote out a handwritten bill of sale, gave me the keys, and said the title was at a lender.\""), .direct("What did you learn when you checked the title?", "\"I went to the DMV after a month and found the car was registered to someone else. The registered owner told me nobody had ever agreed to sell it.\""), .cross("{D} says the relative agreed and changed their mind later. Did you hear that?", "\"I did, but the relative told deputies there was never an agreement to sell the car.\""), .cross("You took the car home with you, didn't you?", "\"I drove it away that day. It was taken back later, after the owner reported it.\""), .cross("Did you check the title before you paid?", "\"No. I relied on what {D} told me, and I did not ask to see a document first.\""), .cross("Did you ask for the title before you paid?", "\"I asked. {D} said it was being held by the lender and would be mailed in a week or two. I thought that was a normal delay.\""), .cross("Did you have the car checked by a mechanic before the sale?", "\"Yes. It passed the check, and I have no complaint about its condition, only that it was never legally mine.\"")],
        theory: ("{D} sold a car that wasn't his.", "A deal that fell through."),
        allocution: "\"I'll pay back what I took.\"",
        truths: ("{DL} had spent the cash on rent within days.", "The relative's text read 'Go ahead and list it, I'll sign when I'm back.'"),
        defendant: [.direct("Did you sell the car to {V}?", "\"I tried to. I had talked with the relative who owned it, and I believed the sale was approved.\""), .direct("What happened to the title?", "\"It was delayed. I told {V} it was at a lender and would be mailed, because that is what I understood.\""), .direct("What did the relative do?", "\"The relative backed out after the sale. I was as surprised as anyone.\""), .direct("What can you tell us about the car?", "\"It belongs to a relative who had been talking about selling it. They said I could list it and handle the buyers while they were out of town.\""), .direct("Why did you sell the car before the title was in hand?", "\"The relative said the title was coming. I took the cash, wrote a bill of sale, and told {V} the title would follow.\""), .direct("What did you do with the money?", "\"I paid rent and some bills. I told myself I'd have the title by the time anyone asked about it.\""), .cross("You took $4,500 in cash before you had a title, didn't you?", "\"I did, and I should not have. I wanted the sale to go through, and I thought the title would follow.\""), .cross("The relative says there was never an agreement. Who is lying?", "\"I do not think the relative is lying exactly. We had a conversation, and I took it as a yes.\""), .cross("What happened to the cash?", "\"I spent it on rent. I was behind, and I used the money right away.\""), .cross("You took $4,500 for a car you didn't own. Isn't that what a scam is?", "\"It looks that way now. I believed I had permission, and when the relative backed out, I was in over my head.\""), .cross("The relative says there was no agreement. Do you have anything in writing?", "\"I have a text that says to go ahead and list it, and I thought that was enough. I should have gotten something signed.\"")],
        openings: ("{V} paid {D} $4,500 in cash for a used car, and {D} promised a title in the mail. It never came, because the car belonged to a relative who never agreed to sell it.", "Listen for the defense evidence, which will show that {D} believed the relative had agreed to the sale. A deal that goes bad is not a crime unless the State proves {D} meant to deceive."),
        closings: ("Cash handed over, a title that was never mailed, and an owner who said no. {D} spent the money on rent within days, and a seller who knows that is not selling in good faith.", "{D} thought the relative had agreed, and that belief is what the case turns on. A sale that falls through is a civil dispute, and a crime requires intent."),
        timeline: [(-10, "{DL} lists the car."), (-7, "{V} pays $4,500."), (0, "{V} learns the car isn't {DL}'s.")],
        identified: "A bill of sale.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let pickupLineSpeeding = SmallCases.make(
        key: "story.pickupLineSpeeding",
        category: .traffic,
        headlines: ["Driver Speeds Through School Pickup Line", "Parents Photograph Truck Weaving Past Crossing Guard"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, in a school zone, on {DATE}.",
        ages: 21...60,
        victim: false,
        summary: "At 3:10 p.m. on {DATE}, a truck sped around a stopped pickup line, weaving past a crossing guard and children. Parents photographed the plate. {D} owns the truck. {DL} says {D.he} did not see the line and was rushing to a medical appointment.",
        state: [E(.video, 3, "Parent Photos", "A truck passes the stopped line at high speed."), E(.statement, 3, "Crossing Guard", "The guard jumped back as it passed.")],
        defense: [E(.statement, 1, "Appointment", "{DL} says {D.he} was rushing to an appointment.")],
        role: "Crossing guard",
        exam: [.direct("What did you see at 3:10 that afternoon?", "\"A truck sped around the stopped pickup line, weaving past me and the children, going much too fast for a school zone.\""), .direct("How close did it come?", "\"About four feet from me. I jumped back to get out of the way, and some of the children were right behind me.\""), .direct("How was the truck identified?", "\"Parents photographed the plate and the truck as it passed. The plate belongs to {D}.\""), .direct("What is your job, and where do you stand at pickup?", "\"I'm the crossing guard at the school's front entrance. I stand in the street with a stop sign at pickup, and the line of parents' cars forms along the curb.\""), .direct("How fast was the truck?", "\"Faster than any car should go there, maybe thirty miles an hour. The limit is fifteen and the truck was weaving around cars that were stopped.\""), .direct("What did you do when you saw it coming?", "\"I stepped back toward the curb and waved my sign. The truck went past within about four feet of me, and children were on the sidewalk.\""), .cross("{D} says there was a rush to a medical appointment, doesn't {D.he}?", "\"Yes, I heard that. But being late does not make it safe to drive past a line of children.\""), .cross("No child was struck, was one?", "\"No, thankfully. That is luck and a quick step backward, nothing more.\""), .cross("Did {D} see the line?", "\"I cannot say. The truck did not slow down, and I do not know what the driver could see.\""), .cross("Did the truck hit anyone or anything?", "\"No. I jumped back and a few children were near the curb, but nobody was struck and nothing was damaged.\""), .cross("Did the driver stop or slow down after passing you?", "\"Not that I saw. The truck kept going down the road, and I took down the plate from the parents' photo.\"")],
        theory: ("{D} sped past children.", "A rushed driver."),
        allocution: "\"I'm very sorry. I never meant to.\"",
        truths: ("{DL} sped in a 15 zone and had been warned twice.", "A text from the clinic told {DL} to arrive by 3:15 or lose the appointment."),
        defendant: [.direct("Were you speeding through the pickup line?", "\"Not much. I was rushing to a medical appointment and I did not see the line until I was nearly past it.\""), .direct("Why were you in such a hurry?", "\"I had an appointment that I could not afford to miss. The clinic told me to arrive on time or lose it.\""), .direct("Did you see the crossing guard?", "\"Only at the last second. I did not realize how close I was, and I felt terrible afterward.\""), .direct("Tell the jury where you were going that afternoon.", "\"To a medical appointment across town. I had been told to arrive by 3:15 or I'd lose the slot, and I'd waited weeks for it.\""), .direct("Did you see the line of cars?", "\"Not until I was almost on it. I was reading a map on my phone and thought I was on a through road.\""), .direct("What did you do after you passed the line?", "\"I kept going, because I was late. I did not realize I'd passed so close to anyone until the deputy called me later.\""), .cross("The speed limit there is 15, isn't it?", "\"Yes. I missed the sign. I know that is not an excuse, but I was not paying attention.\""), .cross("You had been warned about speeding there before, hadn't you?", "\"I may have been. I do not remember the details, and I did not think of it that day.\""), .cross("The appointment was at 5 p.m. Why rush at 3:10?", "\"I wanted to be early. I had other things to do first, and I was running behind on my schedule.\""), .cross("You were in a school zone at pickup. Weren't you required to slow down?", "\"Yes. I missed the sign and I should have been paying attention, and I understand that.\""), .cross("You've been warned about speeding in that area before, haven't you?", "\"I may have been. I honestly don't remember a specific warning.\"")],
        openings: ("At 3:10 in the afternoon, a truck sped around a stopped pickup line outside a school, passing within four feet of a crossing guard and children. Parents photographed the plate, and it belongs to {D}.", "The defense evidence includes a driver rushing to a medical appointment who never saw the line. No child was hurt, and nothing shows {D} meant to put anyone in danger."),
        closings: ("A school zone, a stopped line of children, and a truck passing within four feet of a crossing guard. A driver who is rushing is still responsible for what is in front of the hood.", "{D} did not see the line until it was nearly too late, and no one was touched. A moment of hurry is a mistake, not a crime of recklessness."),
        timeline: [(0, "3:05 p.m.: the pickup line forms."), (0, "3:10 p.m.: the truck passes."), (0, "3:20 p.m.: parents report the plate.")],
        identified: "Parent photographs.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let rifleAtKids = SmallCases.make(
        key: "story.rifleAtKids",
        category: .violent,
        headlines: ["Landowner Points Rifle at Teens Cutting Through Field", "Boys Say Man Threatened to Shoot"],
        law: "assaultPointingGun",
        spec: "Assaulted {V} by pointing a gun at {V.him}, on {DATE}.",
        ages: 35...70,
        victim: true,
        summary: "Three boys cut across {D}'s field on {DATE} on their way to a creek. {D} stepped out of a barn and pointed a rifle at them, shouting that he would shoot. One boy, {V}, filmed it. {DL} says the boys were trampling crops and the rifle was not loaded.",
        state: [E(.video, 3, "Phone Video", "{D} points a rifle and shouts."), E(.statement, 3, "Boys", "All three describe the rifle pointed at them.")],
        defense: [E(.statement, 1, "Not Loaded", "{DL} says the rifle was not loaded.")],
        role: "Teen witness",
        exam: [.direct("What were you and your friends doing that day?", "\"Three of us were cutting across a field on our way to a creek. We had done it before and thought nothing of it.\""), .direct("What happened when {D} came out of the barn?", "\"{D} stepped out with a rifle and pointed it right at us, shouting that {D.he} would shoot. I was frightened and started filming.\""), .direct("What did your video capture?", "\"It shows {D} holding the rifle toward us and yelling. All three of us describe the same thing.\""), .direct("Where is the creek, and how often do you go there?", "\"About half a mile behind the field, down a path. We go there most summer afternoons to fish and skip rocks.\""), .direct("What did {D} say when {D.he} came out of the barn?", "\"{D} shouted that we were trespassing and that {D.he} would shoot if we didn't leave. I started filming because I thought no one would believe us.\""), .direct("What did you do after {D} pointed the rifle?", "\"We backed away, put our hands up, and ran back toward the road. We called a parent, and a deputy came about half an hour later.\""), .cross("Did you know whether the rifle was loaded?", "\"No. I had no idea. I only knew it was pointed at us.\""), .cross("You were on {D}'s field, weren't you?", "\"Yes, we were cutting across it. We did not think we were hurting anything.\""), .cross("Did any of you trample crops or throw anything?", "\"I did not. I cannot speak for every step the others took, but I did not do anything on purpose.\""), .cross("Were you trampling the crops?", "\"We walked along the edge of the field where a path is worn. I don't think we stepped on any plants, but I can't be certain.\""), .cross("Did any of you throw rocks at the barn or carry a slingshot?", "\"No. I had a fishing rod and one of my friends had a tackle box. I never saw anyone throw anything.\"")],
        theory: ("{D} aimed a rifle at children.", "An unloaded warning."),
        allocution: "\"I overreacted. I'm sorry.\"",
        truths: ("A round was in the chamber when deputies arrived.", "The boys had thrown stones at the barn and one carried a slingshot, a neighbor said."),
        defendant: [.direct("Did you point the rifle at the teens?", "\"Yes, to scare them. I wanted them off my field, and I did not want to hurt anyone.\""), .direct("Was the rifle loaded?", "\"No. I believed it was empty when I picked it up. I would never point a loaded rifle at a child.\""), .direct("Why were you so upset?", "\"They had been trampling my crops, and I was tired of it. I lost my temper for a few seconds.\""), .direct("Tell the jury how long you've farmed that land.", "\"Over twenty years. It's my family's land, and I'd lost a lot of corn the summer before to people cutting through.\""), .direct("What did you see that afternoon?", "\"Three young people walking through the rows. I came out of the barn, grabbed the rifle from the door, and told them to get off my field.\""), .direct("Why did you point the rifle at them?", "\"I wanted them to leave. I thought it was empty, and I wasn't going to shoot, but I know it was wrong to point it at anyone.\""), .cross("A round was found in the chamber when deputies arrived, wasn't it?", "\"I forgot it was there. I thought it was empty, and I was wrong.\""), .cross("You shouted that you would shoot, didn't you?", "\"I did. It was a stupid thing to say. I wanted them to run, and I did not mean it.\""), .cross("These were young people, weren't they?", "\"I know. They were kids. I was not thinking clearly, and I regret it deeply.\""), .cross("You said the rifle was empty, and deputies found a round in the chamber. How do you explain that?", "\"I forgot it was there. I'd used it for coyotes the week before and thought I'd emptied it.\""), .cross("The boys filmed you pointing the rifle at them, didn't they?", "\"Yes, and I have watched that video. I can see how frightening it looked, and I should not have raised the rifle toward anyone.\""), .cross("You are the adult in this story, aren't you?", "\"Yes. I am old enough to know better. I should have called the sheriff about the trampled crops rather than stepping out of the barn with a rifle.\"")],
        openings: ("Three teens cut across {D}'s field on the way to a creek. {D} stepped out of a barn, pointed a rifle at them, and shouted that {D.he} would shoot, and one teen recorded it.", "The defense will point you to a farmer tired of trespassers and trampled crops. {D} believed the rifle was empty and wanted only to scare the teens away."),
        closings: ("A rifle pointed at three young people, a threat to shoot, and a round in the chamber when deputies arrived. The video speaks for itself.", "{D} thought the rifle was empty and meant only to chase trespassers off. A frightened person's bad judgment is not the same as an intent to harm."),
        timeline: [(0, "4 p.m.: the boys cross the field."), (0, "4:05 p.m.: {DL} points the rifle."), (0, "4:30 p.m.: deputies arrive.")],
        identified: "A boy's video.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        impact: "I'm afraid of fields now.",
        doctrines: ["selfDefense"],
        genders: ["D": .male, "V": .male])

    static let textbookTheft = SmallCases.make(
        key: "story.textbookTheft",
        category: .property,
        headlines: ["College Bookstore Loses $1,100 in Textbooks to Walkouts", "Staff Notes Student Leaving With Backpack Full"],
        law: "larcenyMerchant",
        spec: "Took textbooks valued at $1,100 from {V}, a college bookstore, without paying, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "A college bookstore lost seven textbooks worth $1,100 in one afternoon on {DATE}. A camera showed {D} loading a backpack in an aisle. {D} later tried to sell the books online. {DL} says the backpack was {D.his} own books from home.",
        state: [E(.video, 3, "Aisle Camera", "{D} loads seven textbooks into a backpack."), E(.digital, 3, "Online Listing", "{D}'s listing for the same seven books.")],
        defense: [E(.statement, 1, "Own Books", "{DL} says the books were {D.his}.")],
        role: "Bookstore manager",
        exam: [.direct("What was missing from the shelf?", "\"Seven books worth about $1,100 in all. We counted the shelf after the camera footage showed it.\""), .direct("How did you learn about the online listing?", "\"A staff member found a listing for the same seven books, and the account belonged to {D}.\""), .direct("How are the textbooks displayed, and how did you notice the shortage?", "\"They stand on open shelves by course number. A clerk doing a shelf check that evening found gaps on two shelves and told me seven titles were missing.\""), .direct("What does the aisle camera show about {D}?", "\"{D} is at the shelf for about five minutes, taking books down one at a time and putting them into a backpack. {D} then walks out through the front without going to a register.\""), .direct("How did you find the online listing?", "\"A staff member searched the titles that night and found a seller posting all seven books. The photos showed our price stickers on the back covers.\""), .direct("How did you work out which textbooks had come from your shelves?", "\"Our price stickers were in the photos of the online listing. Once I matched the titles and edition numbers to our shelf count, I knew those were ours.\""), .cross("{D} says these were {D.his} own books from home. Is that possible?", "\"The books had our store stickers on them. A book from home does not carry our stickers.\""), .cross("The books could have been bought from your store earlier, couldn't they?", "\"Possibly, but we found no receipts for them. I checked our records.\""), .cross("Did {D} try to hide the books?", "\"The camera shows {D} loading them into a backpack and walking toward the exit. I cannot say more about what {D} was thinking.\""), .cross("Couldn't {D} have bought those books from your store earlier and then relisted them?", "\"If so, there would be a sale record and a receipt. I checked and found no purchase of those titles by {D}.\""), .cross("Do used books carry the store's stickers even after a customer buys them?", "\"Sometimes a customer leaves the sticker on. But the books in the listing were marked with this month's prices, which only went on that week.\"")],
        theory: ("{D} took books to resell.", "Own books."),
        allocution: "\"I needed the money.\"",
        truths: ("The listings showed the bookstore's price stickers in photos.", "The books carried a former student's name inside the cover, not the bookstore's."),
        defendant: [.direct("Whose books were those?", "\"They were mine. I brought some books from home to sell, and I was carrying them in my backpack.\""), .direct("Why did you list them online?", "\"I had extra books I did not need, so I listed them to get some money.\""), .direct("Did you take books from the store?", "\"No. I did not take anything from the shelf. I only took what was already mine.\""), .direct("What can you tell us about the books you brought from home?", "\"I had a set of textbooks from a class I'd finished and a couple of extras I picked up from a friend. I carried them in my backpack to sell back.\""), .direct("What were you doing in that aisle?", "\"Rearranging my bag. I took the books out to find my notes and put them back in, and I wasn't taking anything from the shelf.\""), .direct("Why did you list the books online?", "\"The bookstore would only buy back two of them, so I put the rest online to make some money.\""), .cross("The photos in your listing show store price stickers. How do you explain that?", "\"I did not notice the stickers. I took the photos fast and did not look closely.\""), .cross("Do you have receipts for those books?", "\"No. I lost them.\""), .cross("The camera shows you filling a backpack in an aisle. Why do that?", "\"I was organizing my bag in the aisle. It was a place with room to set things down.\""), .cross("The photos show store stickers. How do you explain that?", "\"I bought some of those books used from the same store a year earlier. I didn't peel the stickers off, and I never thought about it.\""), .cross("You don't have receipts for any of the seven books?", "\"No. I lost them, which is why I'm in this position.\"")],
        openings: ("A college bookstore lost seven textbooks worth $1,100 in one afternoon. A camera shows {D} filling a backpack in an aisle, and {D} later listed the same seven books for sale online.", "Jurors will hear that {D} brought books from home and was rearranging a backpack. {D} had no intent to steal anything from that store."),
        closings: ("Seven books, a camera, and an online listing with the store's price stickers in the photos. {D} took them and tried to sell them.", "The State says store stickers prove the theft, but used books pass through many hands. {D} was reorganizing a bag, and no one saw {D} take a book off a shelf."),
        timeline: [(0, "2 p.m.: {DL} enters the bookstore."), (0, "2:20 p.m.: the backpack is filled."), (1, "{DL} lists the books online.")],
        identified: "An aisle camera and online listings.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .indifferent)

    static let golfCartDwi = SmallCases.make(
        key: "story.golfCartDwi",
        category: .traffic,
        headlines: ["Man Drives Golf Cart Down County Road After Cookout", "Deputy Finds Open Cooler and Slurred Speech"],
        law: "dwi",
        spec: "Operated a vehicle on a public road while subject to an impairing substance, on {DATE}.",
        ages: 25...65,
        victim: false,
        summary: "A deputy saw {D} driving a golf cart down a county road at 9 p.m. on {DATE} after a cookout. {D} smelled of alcohol and blew 0.13. {DL} says a golf cart isn't a motor vehicle and the road was the only way home.",
        state: [E(.forensic, 3, "Breath Test", "0.13 at the station."), E(.statement, 3, "Deputy", "{D} drove on a public road with slurred speech.")],
        defense: [E(.statement, 1, "Golf Cart", "{DL} says a golf cart is not a motor vehicle.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you see on {DATE}?", "\"At about 9:05 p.m. I saw {D} driving a golf cart down a county road with no lights on. I followed and made a stop.\""), .direct("What did you notice about {D}?", "\"A strong smell of alcohol, slurred speech, and red eyes. {D} told me about a cookout earlier that evening.\""), .direct("What was the cookout?", "\"It started around 5 p.m. at a neighbor's house. {D} said {D.he} was driving home along the county road.\""), .direct("What did the breath test show?", "\"A 0.13 at the station about an hour later. The test was conducted by a certified operator.\""), .direct("What did you find in the cart?", "\"A cooler held empty cans. I couldn't tell you how many had been drunk by {D} or by others.\""), .direct("What did {D} say about the cart?", "\"That a golf cart isn't a motor vehicle and that the road was the only way home.\""), .cross("Isn't it true the cart can't go faster than about 15 miles an hour?", "\"About that. It's a slow vehicle, and I paced it at about fifteen.\""), .cross("Was {D} weaving or driving erratically?", "\"Slowly and a bit unsteadily, I'd say. I wouldn't call it dangerous, but I had concern about a car coming up behind.\""), .cross("Is there a county ordinance about golf carts?", "\"I believe there is, and I understand it exempts carts capped under 20 mph from some vehicle rules. I can't quote it.\""), .cross("Was it dark when you saw {D}?", "\"Yes, it was dusk and getting darker. The cart didn't have lights and was hard to see.\""), .cross("Was {D} cooperative?", "\"Yes. {D} was polite and did every test I asked for.\"")],
        theory: ("{D} drove drunk on a public road.", "A golf cart exception."),
        allocution: "\"I should have walked.\"",
        truths: ("A cooler in the cart held empty cans.", "A county ordinance listed carts capped under 20 mph as exempt from the vehicle code."),
        defendant: [.direct("What were you doing that evening?", "\"Cookout at a neighbor's. We started around 5, ate, and had some drinks. I started home around nine.\""), .direct("Why did you take the golf cart?", "\"It's the way I get home from that house. The house is a mile down the road, and I've done it a hundred times.\""), .direct("How did you feel when you left?", "\"A little buzzed, but I thought I was fine for a slow ride. I'd had some beers, and I took my time.\""), .direct("Do you believe a golf cart is a motor vehicle?", "\"I don't think so. It's a cart that tops out at 15 mph. I thought it was exempt from the drunk driving law.\""), .direct("Why not walk home?", "\"It's a mile on a dark road with no sidewalk. I figured the cart was safer than walking.\""), .direct("What did you say to the deputy?", "\"That I'd been at a cookout and was heading home on a cart. I did everything the deputy asked.\""), .cross("You drank at the cookout, didn't you?", "\"Yes, several beers over the evening. I won't deny it.\""), .cross("You blew a 0.13?", "\"That's what the machine said. I was surprised, but I accept the number.\""), .cross("You drove on a public road?", "\"Yes, the county road. It was the only way to get home, but it's still a public road.\""), .cross("Your cart had empty cans in a cooler?", "\"Yes, some of them were mine. The cooler was in the cart because we'd ridden around the cookout.\""), .cross("You didn't have lights on the cart?", "\"No. It's just a cart, and I didn't think about lights. I know that's a risk.\"")],
        openings: ("At 9 p.m. a deputy saw {D} driving a golf cart down a county road after an afternoon cookout. {D} smelled of alcohol, spoke slowly, and registered 0.13 at the station.", "{D} was riding a slow golf cart home on the only road available, and the defense says a golf cart is not a motor vehicle under the statute. The State must prove {D} drove a motor vehicle, and it cannot."),
        closings: ("A public road, a cart, empty cans in the cooler, slurred speech, and a 0.13. {D} drove drunk on a county road, and a slow vehicle is still a danger to those around it.", "The county ordinance lists carts capped under 20 mph as exempt from the vehicle code. {D} was going about fifteen on the only road home, and the State has not shown {D} drove a motor vehicle."),
        timeline: [(0, "5 p.m.: the cookout."), (0, "9 p.m.: {DL} drives home."), (0, "9:05 p.m.: a deputy stops the cart.")],
        identified: "A deputy.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let giftCardSwap = SmallCases.make(
        key: "story.giftCardSwap",
        category: .cyber,
        headlines: ["Shopper Swaps Gift Card Barcodes at Store Rack", "Customers Find Empty Cards Bought at Grocery"],
        law: "cardFraud",
        spec: "Obtained value from {V}, a grocery store, by fraud involving gift cards, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "A grocery store received complaints on {DATE} that gift cards bought at its rack were empty. Cameras showed {D} peeling and swapping stickers on a rack of cards and later using the real cards. {DL} says {D.he} was only reading the packaging.",
        state: [E(.video, 3, "Rack Camera", "{D} peels and swaps stickers."), E(.digital, 3, "Card Records", "Seven cards drained at {D}'s phone's address.")],
        defense: [E(.statement, 1, "Reading", "{DL} says {D.he} was just reading the packaging.")],
        role: "Store manager",
        exam: [.direct("What is your role at the grocery store?", "\"I'm the store manager. I handle complaints, supervise the front end, and review our camera footage when something is reported.\""), .direct("What complaints did you receive on {DATE}?", "\"Several customers called saying gift cards they bought from our rack were empty when they tried to use them.\""), .direct("What did the rack camera show?", "\"At about 3 p.m. {D} stands at the gift card rack, peeling and swapping stickers on a number of cards over about twenty minutes.\""), .direct("What does that mean?", "\"The stickers cover the card number and PIN. If you swap them, the customer buys a card the thief already knows and drains the balance.\""), .direct("What did your records show?", "\"Seven cards were drained, and the activity traces to an address linked to {D}'s phone.\""), .direct("How many customers were affected?", "\"Seven so far, with losses of several hundred dollars in total. We made refunds and are still working through them.\""), .cross("Isn't it true the rack is open to anyone?", "\"Yes. It's on the end of an aisle, and any customer can pick up cards, read the packaging, and put them back.\""), .cross("Did other people handle the cards that day?", "\"I saw two other customers handle them on the footage. I didn't see them swap anything.\""), .cross("Did you see a knife in {D}'s hand?", "\"Not clearly. The camera angle shows hands near the cards. I don't see a blade.\""), .cross("How do you know the cards were drained by {D}?", "\"By the address connected to {D}'s phone. I can't say who held the phone.\""), .cross("Did {D} buy any cards at the register?", "\"Not that I saw. {D} left without a purchase.\"")],
        theory: ("{D} swapped gift card stickers.", "Just reading."),
        allocution: "\"I did it. I'm sorry.\"",
        truths: ("A hobby knife was in {DL}'s pocket.", "The rack was open to anyone and two other customers handled the cards that day."),
        defendant: [.direct("Why were you at the gift card rack?", "\"I was reading the packaging. I was thinking of buying a card for a gift and wanted to see the fine print.\""), .direct("Why were you there twenty minutes?", "\"I was reading the terms and also on my phone. I wasn't in a hurry.\""), .direct("Did you peel stickers?", "\"No. I touched the cards to turn them over. I didn't peel anything off or swap anything.\""), .direct("Do you carry a hobby knife?", "\"I do, in my pocket. I use it for crafts and I forgot it was there.\""), .direct("How do you explain the drained cards?", "\"I don't know. My phone address doesn't mean I used those cards, and I can't say who might have used my Wi-Fi.\""), .direct("What would you like the jury to know?", "\"I'm not a thief. I looked at cards in a store and left without buying anything.\""), .cross("The camera shows you peeling stickers, doesn't it?", "\"It shows my hands on the cards. I think it looks like peeling, but I was just handling them.\""), .cross("Seven cards were drained at your phone's address?", "\"That's what I'm told. I can't explain it, and I wasn't aware of it.\""), .cross("You had a hobby knife in your pocket?", "\"Yes. I always carry one, and it was in my pocket.\""), .cross("You stood there for twenty minutes?", "\"I did. I read a lot of packaging, and I take my time.\""), .cross("You didn't buy anything?", "\"Correct. I didn't buy a card because I decided against it.\"")],
        openings: ("On {DATE}, customers who bought gift cards at the grocery store's rack found them empty. The rack camera shows {D} peeling and swapping stickers for twenty minutes, and seven drained cards trace to an address tied to {D}'s phone.", "{D} was reading the packaging on a rack that is open to every customer, and two others handled the cards that day. The defense says the State cannot connect {D}'s hands to the cards that were emptied."),
        closings: ("Twenty minutes at the rack, stickers peeled and swapped, a hobby knife in a pocket, and seven drained cards linked to {D}'s phone. The pieces fit together.", "The rack is open to everyone, two other customers handled the cards, and the camera never shows a knife. The State has a long look at gift cards and an internet address, not proof of who emptied them."),
        timeline: [(0, "3 p.m.: {DL} at the rack."), (0, "3:20 p.m.: stickers swapped."), (1, "Customers report empty cards.")],
        identified: "A rack camera.",
        mood: .indifferent)

    static let churchTreasurerSkim = SmallCases.make(
        key: "story.churchTreasurerSkim",
        category: .whiteCollar,
        headlines: ["Church Treasurer Accused of Skimming Offering Cash", "Deacon Notes Deposits Smaller Than Counted"],
        law: "embezzlement",
        threshold: 6,
        spec: "Embezzled $5,300 entrusted to {D} by {V}, a church, on {DATE}.",
        ages: 35...70,
        victim: true,
        summary: "Over a year ending {DATE}, a church's bank deposits ran $5,300 below the weekly offering totals recorded by counters. {D}, the treasurer, prepared every deposit. {DL} says the counters misrecorded and the shortage was fees.",
        state: [E(.document, 3, "Deposit Records", "Deposits $5,300 below counter totals."), E(.document, 2, "Counter Sheets", "Weekly totals signed by two counters.")],
        defense: [E(.statement, 1, "Fees", "{DL} says the shortage was bank fees.")],
        role: "Church deacon",
        exam: [.direct("What is your role at the church?", "\"I'm a deacon. Part of my duty is overseeing the church's finances, along with the treasurer and the counters who handle the offering.\""), .direct("How does the offering process work?", "\"Two counters tally the offering each Sunday and sign a sheet. The treasurer then prepares the bank deposit and takes it to the bank.\""), .direct("What did you find?", "\"Over about a year, deposits ran $5,300 below the weekly totals on the counter sheets. The first short deposit was about a year ago.\""), .direct("How did you discover it?", "\"About thirty days before I raised it, I audited the records. I compared each week's sheet to the bank statement.\""), .direct("Who prepared every deposit?", "\"{D}, the treasurer. Every deposit slip in the year was prepared and signed by {D}.\""), .direct("What did {D} say?", "\"{D} said the counters misrecorded and that bank fees explained the difference. {D} didn't have documents supporting that.\""), .cross("Isn't it true more than one person handles the cash before it is deposited?", "\"Yes. Counters count it, and it's in the church safe until deposited. Others have access.\""), .cross("Did the counters' sheets have corrections?", "\"Some did. The counters rotate and the handwriting changes, so a few weeks show crossed-out numbers.\""), .cross("Do bank fees apply to the church's account?", "\"There are a few small fees, but nothing near $5,300. I checked the statements.\""), .cross("Was every week short?", "\"Not every week. Some deposits matched the sheets, and the shortages fell into a pattern I can't fully explain.\""), .cross("Did you see {D} take money?", "\"No. Nobody saw it. I only have the records and the difference.\"")],
        theory: ("{D} skimmed the offering.", "Bank fees and miscounts."),
        allocution: "\"I took it. I'm sorry.\"",
        truths: ("{DL} had a personal loan paid off in the same period.", "The counters' tally sheets showed three handwritings and several corrections every week."),
        defendant: [.direct("What is your role as treasurer?", "\"I prepare the weekly deposit, reconcile the bank statement, and report to the finance team. I've done it for years.\""), .direct("What do you think caused the shortfall?", "\"The counters' sheets aren't always accurate. Different people count each week, with different handwriting and mistakes.\""), .direct("What about the bank fees?", "\"There are fees on some deposits and returned items. They add up over a year, and I think they account for part of it.\""), .direct("Did you take offering money?", "\"No. I'd never take a dollar from the church. I've given my time and money to that church for years.\""), .direct("What did you do when the deacon raised it?", "\"I offered to go through the records together. I wanted to find the mistakes.\""), .direct("What happened with your personal loan?", "\"I paid off a loan that year, using savings and a tax refund. It had nothing to do with the offering.\""), .cross("You prepared every deposit, didn't you?", "\"Yes, every one. That was my job, and no one else touched the slips.\""), .cross("The deposits ran $5,300 short?", "\"That's what the deacon says. I can't dispute the arithmetic, but I can dispute the reason.\""), .cross("You can't show the fees equal that amount?", "\"No. I haven't gotten statements to prove that, and I know it's a gap.\""), .cross("You paid off a loan during the same year?", "\"I did. I'd saved for it and I also had help from a refund.\""), .cross("You never reported the sheets as inaccurate?", "\"I mentioned it a few times, but I didn't write anything down. I wish I had.\"")],
        openings: ("Over one year, the church's bank deposits ran $5,300 below the weekly offering totals recorded by the counters. {D}, the treasurer, prepared every deposit, and the State will show the shortfall followed {D}'s hands.", "The counters rotated, their tally sheets show three different handwritings and weekly corrections, and bank fees nibble at deposits. The defense says a messy count is not a theft."),
        closings: ("Fifty-two weeks of deposits, $5,300 missing, and one person who prepared every slip. {D} also paid off a personal loan in that same year.", "Three handwritings, weekly corrections, and bank fees that no one has fully tallied. The State has a gap in the numbers, and a gap is not proof that {D} took the money."),
        timeline: [(-365, "The first short deposit."), (-30, "The deacon audits."), (0, "The totals are compared.")],
        identified: "Deposit records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "Our pastor wept.")

    static let liquorStoreHoldup = SmallCases.make(
        key: "story.liquorStoreHoldup",
        category: .robbery,
        headlines: ["Clerk Handed Over $640 After Man Threatened Him at Liquor Store", "Store Camera Shows Man With Hand in Pocket"],
        law: "commonLawRobbery",
        threshold: 7,
        spec: "Took $640 from the person and presence of {V}, a liquor store clerk, by threatening {V.him}, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "A man walked into a liquor store at 8:50 p.m. on {DATE}, kept a hand in his pocket, and told {V}, the clerk, to empty the register or be shot. {V} handed over $640. A camera captured the man. {D} was stopped a mile away in a car matching the description. {DL} says {D.he} was driving home from work.",
        state: [E(.video, 3, "Store Camera", "A man with a hand in a pocket takes cash."), E(.physical, 3, "Cash", "$640 in a bag, found in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Driving Home", "{DL} says {D.he} was driving home from work.")],
        role: "Liquor store clerk",
        exam: [.direct("What happened at 8:50 that evening?", "\"Someone walked in, kept a hand in a pocket, and told me to empty the register or I would be shot.\""), .direct("Did you see a weapon?", "\"No, only the hand in a pocket. I could not tell what was in it, and I did what I was told.\""), .direct("How much did you hand over?", "\"$640 from the register. The person put it in a bag and left.\""), .direct("Describe the person who came in.", "\"Average height, dressed in dark clothes, with a cap pulled low and a cloth over the lower face. The person kept one hand in a jacket pocket the whole time.\""), .direct("What exactly was said?", "\"The person said to empty the register or I would be shot. The voice was low and calm, and the person didn't raise it.\""), .direct("What happened after you handed over the money?", "\"The person took the cash, backed out the door, and I called 911 right away. The whole thing took under a minute.\""), .cross("No weapon was ever found, was one?", "\"No. Nothing was found, and I never saw a gun.\""), .cross("The person's face was covered, wasn't it?", "\"Yes, there was a cap and a mask. I could not see the face.\""), .cross("How can you say it was {D}?", "\"I cannot identify {D} by face. I only know what the camera and the deputies found.\""), .cross("Did you see which direction the person went?", "\"Only that the person turned right out the door. I didn't see a vehicle, and I stayed behind the counter.\""), .cross("Were you able to pick {D} out of a lineup?", "\"No. The face was covered, so I could not identify anyone by looking at {D} later.\"")],
        defenseRole: "Defendant's coworker",
        defenseExam: [.direct("When did {D} clock out that evening?", "\"At 8:15 p.m. I saw {D} leave work, and I remember because we were closing the shop.\""), .direct("How far does {D} live from the liquor store?", "\"About ten minutes. It is not far from our workplace.\""), .direct("Did {D} say where {D.he} was going?", "\"Home. {D} said {D.he} was tired after the long shift and was heading straight there.\""), .direct("How do you know {D}?", "\"We work the same shift at the warehouse. I've known {D} for about three years.\""), .direct("What time did your shift end that day?", "\"8:15. We punch out together at the time clock, and I saw {D} head toward the parking lot.\""), .direct("Did {D} say anything about plans after work?", "\"Just that {D} was tired and wanted to get home and eat. {D} didn't mention stopping anywhere.\""), .cross("Did you see {D} after clocking out?", "\"No. I only know when {D} clocked out. I do not know where {D} went after that.\""), .cross("Could {D} have reached the store by 8:50?", "\"Yes, it is possible. Ten minutes of driving puts {D} there well within that time.\""), .cross("Did {D} seem nervous that day?", "\"No. {D} seemed normal to me that day, just tired like everyone at the end of a shift.\""), .cross("Did you see {D} after the parking lot?", "\"No. I went home the other way and didn't see {D} again that night.\""), .cross("How long does the drive from the warehouse to the liquor store take?", "\"About twenty minutes in normal traffic. Ten minutes if the roads are empty, which they usually are that late.\"")],
        theory: ("{D} robbed a clerk.", "A worker driving home."),
        allocution: "\"I'm sorry for scaring you.\"",
        truths: ("A mask and a cap were in {DL}'s trunk.", "{DL} bought a $23 drive-through meal five miles away at 8:45 p.m., the receipt shows."),
        defendant: [.direct("Did you rob the store?", "\"No. I did not rob anyone. I was driving home from work that evening.\""), .direct("Where did the cash in your car come from?", "\"It was my pay and some savings. I keep cash in my car, and I did not take it from any register.\""), .direct("Why did you have a cap and a mask?", "\"It was winter, and I wear them to stay warm. They are just part of what I keep in the car.\""), .direct("Where did you work that day, and when did you finish?", "\"At a warehouse across town. I clocked out at 8:15 and started driving home.\""), .direct("What route did you take home?", "\"The main road, and it passes near the liquor store. I stopped for a drive-through meal and then headed on.\""), .direct("What happened when you were pulled over?", "\"A deputy stopped me about a mile from the store and asked where I was coming from. I said work, and I told the truth about the stop for food.\""), .cross("A bag of $640 was in your car, wasn't it?", "\"Yes, but it was my own money. It matches the amount by coincidence.\""), .cross("You were stopped a mile from the store in a car matching the description, weren't you?", "\"I was driving home. Plenty of cars look like mine.\""), .cross("You say you were driving home. What route did you take?", "\"The usual one. It goes past that store, which is why I was nearby.\""), .cross("The cash found in your car matches the total taken. How do you explain that?", "\"It was my paycheck and some savings. I keep cash in a bag in the car because I don't trust my account.\""), .cross("You were a mile from the store ten minutes after a robbery. Isn't that the route a robber would take?", "\"It's also the route home for me and a lot of other people. I didn't know there had been a robbery until the deputy told me.\"")],
        openings: ("At 8:50 on a weeknight, someone with a hand in a pocket told a liquor store clerk to empty the register or be shot and left with $640. A mile away, deputies stopped {D} and found a bag of cash in the car.", "The defense witnesses will explain that {D} clocked out and was driving home. No weapon was found, no face was seen, and the cash was {D}'s own."),
        closings: ("A masked person took $640 at 8:50, and a mile away {D} was stopped with $640 in a bag. A coincidence that exact is no coincidence.", "No face, no weapon, and a worker driving home on a route past that store. The State has shown a car and a sum of money, and neither proves a robbery."),
        timeline: [(0, "8:15 p.m.: {DL} clocks out."), (0, "8:50 p.m.: the holdup."), (0, "9:05 p.m.: {DL} is stopped a mile away.")],
        identified: "A store camera and a traffic stop.",
        mood: .wantsConviction,
        impact: "I still hear 'be shot'.",
        genders: ["D": .male, "V": .male])

    static let bakeryRearBreakin = SmallCases.make(
        key: "story.bakeryRearBreakin",
        category: .property,
        headlines: ["Bakery's Rear Door Forced, Register and Ovens Tampered", "Baker Finds Flour Trail Leading Out"],
        law: "feloniousBE",
        threshold: 6,
        spec: "Broke and entered a building of {V}, a bakery, with intent to commit larceny therein, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "A baker found the rear door forced and the register emptied of $780 at 4 a.m. on {DATE}. A flour trail led to the alley. A camera at the next shop showed a figure with flour on his jeans. {D}'s jeans, seized later, had flour traces. {DL} says {D.he} baked bread at home.",
        state: [E(.physical, 3, "Jeans", "Jeans with flour traces matching the bakery.", .search), E(.video, 2, "Next-Door Camera", "A figure with pale marks on his jeans enters the alley.")],
        defense: [E(.statement, 1, "Home Baking", "{DL} says {D.he} bakes bread at home.")],
        role: "Bakery owner",
        exam: [.direct("What did you find at 4 a.m. on {DATE}?", "\"I arrived at the bakery to start the bread and found the rear door forced and the register emptied of $780.\""), .direct("What else did you notice?", "\"A trail of flour on the floor that led out the back door and into the alley. It was clearly someone's footprints.\""), .direct("What kind of flour was it?", "\"A special grain I buy in bulk, which makes our rye bread. It's rare around here and I buy it from a particular supplier.\""), .direct("What did the camera next door show?", "\"At 3:30 a.m. a figure with pale marks on the jeans entered the alley. At about 3:50 the rear door was forced.\""), .direct("How did {D} become involved?", "\"Deputies seized {D}'s jeans later. They had flour traces that the lab said matched the grain used at the bakery.\""), .direct("What was the damage?", "\"$780 from the register and a broken door that cost several hundred more to repair.\""), .cross("Isn't it true you can't identify the figure on the camera?", "\"I can't. The video is dark and the person is far away. I can only say there are pale marks on the jeans.\""), .cross("Is the flour sold at other places?", "\"I'm told it's sold at a grocery store in town. I didn't know that before, and I haven't checked every shelf.\""), .cross("Did anyone see {D} at the bakery?", "\"No. No one has said that. There's only the flour trace on the jeans.\""), .cross("Could someone get flour on jeans at a store?", "\"Yes, if they handle or spill a bag. I can't say how it got there.\""), .cross("Did you find the cash?", "\"No. I never saw the $780 again, and nothing was found in {D}'s car or home.\"")],
        theory: ("{D} broke in and took cash.", "A home baker."),
        allocution: "\"I did it. I'm sorry.\"",
        truths: ("The flour matched a rare grain the bakery used.", "The bakery's flour is sold at the grocery where {DL} works."),
        defendant: [.direct("Where were you at 3:30 a.m.?", "\"At home asleep. I wake up early for work, so I'm in bed by ten on weeknights.\""), .direct("Why was there flour on your jeans?", "\"I bake bread at home, and I work at the grocery store that sells that flour. I'm around it all the time.\""), .direct("Where do you work?", "\"At a grocery in town. I stock shelves, including the flour. Bags break and spill, and my clothes get dusty.\""), .direct("Have you ever been to the bakery?", "\"I've bought bread there a few times. I've never been in the alley, and I don't know the rear door.\""), .direct("Did you take the money?", "\"No. I wouldn't know how to break into a door, and I've never taken anything from anyone.\""), .direct("What did you tell the deputies?", "\"That I work at the store with the flour and that I bake. They took my jeans and I didn't object.\""), .cross("The flour on your jeans matched the bakery's grain?", "\"That's what the lab said. It's sold where I work, so it's not surprising.\""), .cross("You live near the bakery, don't you?", "\"A few blocks away. I walk past it sometimes, and it's a small town.\""), .cross("You can't prove you were home at 3:30?", "\"No. I live alone, and I was asleep. I can't give you a witness.\""), .cross("The jeans are yours?", "\"Yes. I wear them most days, including to work.\""), .cross("You bake bread at home with the same flour?", "\"Sometimes, when I can get it at a discount. I buy small bags, and I know that connects me to it.\"")],
        openings: ("A baker arrived at 4 a.m. to find the rear door forced, $780 gone from the register, and a trail of flour leading to the alley. A camera next door shows a figure with pale marks on the jeans, and {D}'s jeans carried flour traces that match the bakery's grain.", "{D} works at a grocery that sells that flour and bakes at home, so flour on the jeans is a fact of everyday life. The defense says the camera shows no face and the State has no cash or witness."),
        closings: ("A rare grain, a trail to the alley, pale marks on the jeans, and flour traces on {D}'s jeans that match. These facts point to {D}, who lives a few blocks away.", "The flour is sold in the store where {D} works, {D} bakes at home, and nobody saw {D} at the door. A dusty pair of jeans does not prove a break-in."),
        timeline: [(0, "3:30 a.m.: a figure enters the alley."), (0, "3:50 a.m.: the rear door is forced."), (0, "4 a.m.: the baker arrives.")],
        identified: "Flour traces.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        genders: ["D": .male])

    static let packagedMarijuana = SmallCases.make(
        key: "story.packagedMarijuana",
        category: .drugs,
        headlines: ["Bags and Scale Found in Apartment During Welfare Check", "Deputy Counts 28 Packaged Bags of Marijuana"],
        law: "pwisd",
        threshold: 6,
        spec: "Possessed with intent to sell or deliver marijuana, on {DATE}.",
        ages: 19...40,
        victim: false,
        summary: "Deputies doing a welfare check on {DATE} saw a scale and baggies on a table in {D}'s apartment. A search found 28 bags of marijuana and $1,300 in small bills. {DL} says {D.he} bought in bulk for personal use and the cash was rent.",
        state: [E(.physical, 3, "Packaged Bags", "28 bags, scale, and baggies.", .search), E(.physical, 2, "Cash", "$1,300 in small bills.", .search)],
        defense: [E(.statement, 1, "Personal Use", "{DL} says {D.he} bought in bulk for personal use.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why were you at the apartment?", "\"We were doing a welfare check. Through the door I saw a scale and baggies on a table in plain view.\""), .direct("What did the search turn up?", "\"Twenty-eight bags of marijuana, already packaged, along with the scale and a roll of empty baggies.\""), .direct("Was any cash found?", "\"Yes, $1,300 in small bills. It was in several places in the apartment.\""), .direct("What was the reason for the welfare check?", "\"A relative called and said they hadn't heard from {D} in several days and were worried. We went to the apartment to make sure {D} was okay.\""), .direct("What did you see from the doorway?", "\"A digital scale and a roll of small baggies on the table near the door. A strong smell of marijuana came from inside.\""), .direct("How were the bags arranged when you searched?", "\"Twenty-eight individual bags in a shoebox, each holding a similar amount. A plastic tub with more loose marijuana sat next to them.\""), .cross("{D} says the marijuana was for personal use, doesn't {D.he}?", "\"That is what {D} says. Twenty-eight separate bags is a lot for personal use, in my experience.\""), .cross("The cash could have been rent, couldn't it?", "\"It could be. I cannot rule that out. Small bills are common for rent paid in cash.\""), .cross("Was anything found that tied {D} to a sale?", "\"Texts on a phone, which I reviewed. I did not see anyone buy from {D}.\""), .cross("Did you see {D} sell anything or hand anything to anyone?", "\"No. We found no buyers at the apartment and no sale in progress.\""), .cross("Was anyone else in the apartment?", "\"No. {D} was alone when we arrived and was cooperative throughout.\"")],
        theory: ("{D} packaged marijuana to sell.", "A bulk buyer."),
        allocution: "\"I'm sorry.\"",
        truths: ("A phone held sale texts.", "The scale was a kitchen scale {DL} used for baking."),
        defendant: [.direct("Did you sell marijuana?", "\"No. I never sold anything. I bought it in bulk because it is cheaper, and it was for my own use.\""), .direct("Why was it in small bags?", "\"They were easier to carry. I separated it so I did not have to carry a large amount.\""), .direct("What was the scale for?", "\"I use it for cooking and baking. It is a kitchen scale, and I weigh ingredients on it.\""), .direct("How much marijuana do you use in a typical week?", "\"A few grams a day, mostly in the evening to help me sleep. I buy in bulk because it's cheaper.\""), .direct("Why were there twenty-eight bags?", "\"I weigh out a month's supply at a time and bag it so it stays fresh. Each bag is a few days' worth.\""), .direct("What was the cash for?", "\"Rent. I pay my landlord in cash and I had just withdrawn it from my account.\""), .cross("Twenty-eight bags. Isn't that more than one person uses?", "\"Over a long time it would not be. I bought a lot to save money.\""), .cross("The texts on your phone mention sales, don't they?", "\"They are with friends. We joke, and it does not mean I sold anything.\""), .cross("$1,300 in small bills. Where did it come from?", "\"It was for my rent. I had saved it in cash for the month.\""), .cross("The texts on your phone mention sales. Can you explain?", "\"They're with friends. We joke about prices and who's buying, and none of it was a real deal.\""), .cross("A scale, baggies, and $1,300 in small bills. Doesn't that look like a sale?", "\"I understand how it looks. I use the scale for cooking and I keep my money in small bills, because that's how I get paid.\"")],
        openings: ("During a welfare check, deputies saw a scale and baggies on a table in {D}'s apartment. A search found 28 bags of marijuana and $1,300 in small bills.", "The defense case is that {D} bought in bulk for personal use, that the scale is a kitchen scale, and that the cash was set aside for rent."),
        closings: ("Twenty-eight packaged bags, a scale, a roll of baggies, and $1,300 in small bills. Together they describe a business, not a hobby.", "Nobody saw {D} sell anything. A kitchen scale and a stash bought in bulk are not evidence of dealing. The State must prove more than suspicion."),
        timeline: [(0, "A welfare check."), (0, "A deputy sees the scale."), (0, "A warrant search.")],
        identified: "A deputy.",
        aggravating: ["The offense involved sale or delivery"],
        mood: .indifferent,
        doctrines: ["searchSeizure"])

    static let neighborStalking = SmallCases.make(
        key: "story.neighborStalking",
        category: .family,
        headlines: ["Man Watches Neighbor's Windows Nightly, Records Say", "Neighbor Keeps Log of Flashlight Beams"],
        law: "stalking",
        threshold: 6,
        spec: "Willfully harassed {V} on more than one occasion without legal purpose, on {DATE}.",
        ages: 28...65,
        victim: true,
        summary: "For two months ending {DATE}, {V} saw a flashlight in the yard at night and found notes on the door. A trail camera showed {D}, a neighbor, standing at the fence line. {DL} says {D.he} was checking on a stray cat.",
        state: [E(.video, 3, "Trail Camera", "{D} at the fence line at 1 a.m."), E(.document, 2, "Notes", "Eight notes on {V}'s door.")],
        defense: [E(.statement, 1, "Stray Cat", "{DL} says {D.he} was checking on a cat.")],
        role: "Neighbor",
        exam: [.direct("Tell the jury who you are and where you live in relation to {D}.", "\"I live in the house next to {D}'s, with a wooden fence between our backyards. We've been neighbors for about three years and have spoken maybe a handful of times.\""), .direct("What did you see in your yard over those two months?", "\"A flashlight moving in the yard at night. It happened many times, and each time I felt unsafe in my own home.\""), .direct("What did you find on your door?", "\"Eight notes, all signed. They were left over the same weeks, and I saved every one.\""), .direct("What did your trail camera show?", "\"{D}, my neighbor, standing at the fence line at 1 a.m. holding a flashlight.\""), .direct("How many times did you see the flashlight?", "\"At least six times over two months. It was always after midnight, and it moved slowly along the fence line and across my yard.\""), .direct("What did the notes say?", "\"Short handwritten messages signed with {D}'s name, about the fence, the weather, and whether I was home. After the fifth one I stopped reading them and started saving them.\""), .cross("{D} says it was about a stray cat. Did you see a cat?", "\"No. I never saw a cat in my yard, and the camera does not show one.\""), .cross("{D} never threatened you, did {D.he}?", "\"Never. There were no threats. It was just the watching that frightened me.\""), .cross("The notes were neighborly in tone, weren't they?", "\"Some were polite. But eight of them, and a flashlight at night, is more than neighborly.\""), .cross("Did {D} ever come onto your property or speak to you in person?", "\"Not to speak to me. The camera shows {D} at the fence, and on one night I saw a figure walking along my side but couldn't identify who.\""), .cross("Did you ask {D} directly to stop?", "\"I put a note on {D}'s door after the fourth note asking for no more contact. The notes continued, and that's when I called deputies.\"")],
        theory: ("{D} watched a neighbor.", "A cat check."),
        allocution: "\"I couldn't stop. I'm sorry.\"",
        truths: ("{DL} had a pair of binoculars on the fence post.", "A vet record showed {DL} had been treating a stray cat found by the fence."),
        defendant: [.direct("Were you watching {V}'s home?", "\"No. I was never watching {V.him}. I was checking on a stray cat near the fence line.\""), .direct("What about the notes?", "\"They were neighborly. I was introducing myself and asking if {V.he} had seen the cat.\""), .direct("Why were you out at 1 a.m.?", "\"I have insomnia. I go outside at night to clear my head, and I look for the cat.\""), .direct("Tell the jury why you were outside at 1 a.m.", "\"I have trouble sleeping. When I can't sleep I walk around the yard with a flashlight to clear my head.\""), .direct("Describe the stray cat for the jury.", "\"A stray started coming around the fence about two months ago. I've been leaving food out and checking on it at night when it's most active.\""), .direct("Why did you leave notes for {V}?", "\"I wanted to introduce myself and ask whether the cat was {V.his}. I kept writing because I never got an answer.\""), .cross("There were binoculars on your fence post, weren't there?", "\"Yes, for birds. I watch birds in the morning, and I leave them there.\""), .cross("Eight notes. Doesn't that seem like a lot?", "\"It was probably too many. I kept hoping to hear back, and I should have stopped.\""), .cross("Why is there no cat on the trail camera?", "\"The cat is shy. It came and went, and I do not control it.\""), .cross("Eight notes and no reply. Why didn't you stop after the second?", "\"I kept thinking {V} might not have seen them. I realize now that it may have felt like too much.\""), .cross("You had binoculars on the fence post. What were they for?", "\"Birds. I like to watch them early in the morning, and the fence is the best place to see the trees.\"")],
        openings: ("For two months, {V} saw a flashlight in the yard at night and found eight notes on the door. A trail camera shows {D}, a neighbor, standing at the fence line at 1 a.m.", "Weigh the defense proof, which will show that {D} was looking for a stray cat and has insomnia. The notes were neighborly, and nothing threatening was ever said."),
        closings: ("A flashlight at night, eight notes, and a trail camera picture of {D} at the fence at 1 a.m. A neighbor does not need binoculars to find a cat.", "No threats, no touching, and a neighbor who treated a stray. A flashlight and a note are not stalking. The State has to prove something more."),
        timeline: [(-60, "{V} first sees the flashlight."), (-30, "The first note."), (0, "The trail camera records {DL}.")],
        identified: "A trail camera.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let nursingAideNeglect = SmallCases.make(
        key: "story.nursingAideNeglect",
        category: .family,
        headlines: ["Nursing Home Aide Left Resident on Floor for Hours", "Staff Records Show No Checks Overnight"],
        law: "patientNeglect",
        threshold: 7,
        spec: "Willfully neglected {V}, a resident of a care facility, resulting in serious injury, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "{V}, a resident of a nursing home, was found on the floor with a hip fracture at 6 a.m. on {DATE}. Records showed no overnight checks signed by {D}, the aide assigned. {DL} says {D.he} made rounds and forgot to chart.",
        state: [E(.document, 3, "Care Log", "No checks charted from 11 p.m. to 6 a.m."), E(.document, 3, "Door Alarm Log", "A bed alarm sounded at 1:20 a.m. and was silenced at 1:22.")],
        defense: [E(.statement, 1, "Forgot to Chart", "{DL} says {D.he} made rounds and forgot to chart.")],
        role: "Nurse supervisor",
        exam: [.direct("What did you find at 6 a.m.?", "\"{V} was on the floor of the room with a fractured hip. The staff called me, and I came right away.\""), .direct("What did the logs show?", "\"The care log shows no checks charted from 11 p.m. to 6 a.m., and the bed alarm sounded at 1:20 and was silenced at 1:22.\""), .direct("Who was assigned to {V} that night?", "\"{D} was the aide assigned. The policy requires hourly checks, and each one has to be charted.\""), .direct("What is your role, and how do you supervise the overnight shift?", "\"I'm the nurse supervisor for the facility. I set the staffing, review the charts each morning, and respond if there's an incident.\""), .direct("What does the door alarm log show about the night in question?", "\"A bed alarm sounded in {V}'s room at 1:20 a.m. and was silenced at 1:22 a.m. using a badge. No one charted anything about the alarm.\""), .direct("What condition was {V} in when staff found {V.him}?", "\"On the floor beside the bed, awake and in pain, with a visible swelling at the hip. {V.he} had been there long enough that {V.his} gown was damp and cold.\""), .cross("Rounds happen even when they are not charted, don't they?", "\"They can. But the chart is how we prove it. If it is not charted, I cannot say that it happened.\""), .cross("The unit was understaffed that night, wasn't it?", "\"Yes. We were short, and I know that makes the work harder.\""), .cross("Did {D} silence the alarm?", "\"The log shows it was silenced from {D}'s badge. I do not know what {D} did next.\""), .cross("Can an alarm be silenced from a distance with a badge?", "\"The system requires the badge to be held at the panel in the room. It cannot be silenced from the hallway.\""), .cross("How many aides were assigned to that floor that night?", "\"Two, when the policy calls for three. We'd had a call-out and couldn't cover it.\"")],
        defenseRole: "Overnight nurse",
        defenseExam: [.direct("Did {D} check on residents that night?", "\"I saw {D} at the desk several times during the night, and I also saw {D} walking the hall with a chart.\""), .direct("Was the unit busy?", "\"Very busy. We were short-staffed that night, and everyone on the floor was running from room to room.\""), .direct("Did {D} seem to be doing the job?", "\"As far as I could tell, yes. {D} was working hard like the rest of us on the unit.\""), .direct("What was your role that night?", "\"I was the overnight nurse on the unit, working with {D} and one other aide for about thirty residents.\""), .direct("How busy was the shift?", "\"Very. One resident was ill, another had a family emergency, and we were short an aide, so everyone was stretched.\""), .direct("What did you see {D} doing?", "\"Moving from room to room, answering call lights, and helping residents to the bathroom. {D} was constantly on the move.\""), .cross("Did you see {D} for the whole night?", "\"Most of the night, yes. Not every single minute, because I had my own residents to see.\""), .cross("Could you see the desk from where you were?", "\"Only partly. My view of the desk was not complete from where I was working.\""), .cross("Did you see {D} check on {V}?", "\"No. I did not personally see that specific check on {V}, and I cannot say it did not happen.\""), .cross("Did you see {D} silence the alarm?", "\"No. I was in another room and I heard it, but I didn't see who silenced it.\""), .cross("Could {D} have been in {V}'s room during the night without you seeing?", "\"It's possible. I didn't have a view of that hallway and I couldn't watch every door.\"")],
        theory: ("{D} left a resident on the floor.", "An understaffed shift."),
        allocution: "\"I failed {V}. I'm sorry.\"",
        truths: ("The bed alarm was silenced from {DL}'s badge.", "The nurse's view of the desk was partial."),
        defendant: [.direct("Did you check on {V}?", "\"I made rounds. I walked the hall and looked in on residents, including {V}.\""), .direct("What happened with the alarm?", "\"I silenced it. I thought it was a false alarm and I intended to come back.\""), .direct("Why didn't you chart the checks?", "\"I forgot. We were short-staffed, and I got behind on the paperwork.\""), .direct("Describe your shift that night.", "\"I started at eleven and had nine residents assigned. We were short, and I was moving between rooms all night.\""), .direct("What do you remember about the alarm at 1:20?", "\"I was in another room helping a resident, and I silenced it on my way past. I thought it was a false alarm and that I'd come back to check.\""), .direct("Did you get back to the room?", "\"I meant to, but I got pulled into another resident's care. I'm not sure when I got back, and I'm sorry I didn't chart.\""), .cross("The alarm sounded at 1:20. Why didn't you respond?", "\"I was busy with another resident. I should have gone back.\""), .cross("You silenced the alarm and did not go to the room, did you?", "\"I intended to. I did not get back to it, and I regret that.\""), .cross("Four hours with no charted checks. How is that rounds?", "\"I did the rounds. I did not chart them, and I know that is a problem.\""), .cross("You silenced an alarm and didn't check the room. Isn't that exactly what the alarm is for?", "\"Yes. I should have gone in right away, and I think about it every day.\""), .cross("No checks were charted for seven hours. How do you explain that?", "\"I was busy and I planned to chart at the end of the shift. Then I ran out of time.\"")],
        openings: ("{V}, a nursing home resident, was found on the floor with a broken hip at 6 a.m. The care log shows no checks charted all night, and a bed alarm was silenced at 1:22 from the aide's badge.", "Jurors will hear that {D} made rounds on a short-staffed unit and simply failed to chart them. A paperwork failure is not neglect."),
        closings: ("A bed alarm silenced at 1:22, no checks charted for seven hours, and a resident on the floor at dawn. The record shows no one was watching {V}.", "{D} was working a short-staffed shift and made rounds. Missing paperwork is not proof of missing care, and the State has not shown {D} knowingly ignored a resident."),
        timeline: [(0, "11 p.m.: {DL}'s overnight shift begins."), (1, "1:20 a.m.: the bed alarm sounds."), (1, "1:22 a.m.: {DL}'s badge silences it."), (1, "6 a.m.: {V} is found.")],
        identified: "Care logs and an alarm log.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "My mother lay there for hours.")

    static let roommateStabbing = SmallCases.make(
        key: "story.roommateStabbing",
        category: .violent,
        headlines: ["Man Found Dead in Shared Apartment After Fight Over Rent", "Roommate Seen Leaving With Bloody Shirt"],
        law: "murder2",
        threshold: 8,
        spec: "Unlawfully killed {V} with malice, on {DATE}.",
        ages: 22...50,
        victim: true,
        summary: "{V} was found stabbed to death in a shared apartment on {DATE} after a neighbor heard shouting about rent. A camera showed {D}, the roommate, leaving with a bag at 11:40 p.m. A bloody shirt was in a dumpster. {DL} says {D.he} left before the fight and found {V} dead on return.",
        state: [E(.video, 3, "Hallway Camera", "{D} leaves with a bag at 11:40 p.m."), E(.forensic, 3, "Bloody Shirt", "{V}'s blood on a shirt in the dumpster with {D}'s DNA inside the collar."), E(.statement, 2, "Neighbor", "Shouting about rent at 11:15 p.m.")],
        defense: [E(.statement, 1, "Left Earlier", "{DL} says {D.he} left before the fight.")],
        role: "Police detective",
        exam: [.direct("What did you find at the apartment?", "\"{V} had been stabbed in the chest. The apartment showed signs of a struggle, and a neighbor had heard shouting about rent around 11:15.\""), .direct("What did the hallway camera show?", "\"{D}, the roommate, leaving with a bag at 11:40 p.m. That was less than half an hour after the shouting.\""), .direct("What was found in the dumpster?", "\"A shirt with {V}'s blood on it. The lab found {D}'s DNA inside the collar.\""), .direct("Describe the apartment when you entered.", "\"{V} was on the kitchen floor with a single stab wound to the chest. A chair was knocked over and a mug lay broken near the sink. The front door was unlocked.\""), .direct("What did the neighbor tell you?", "\"The neighbor said there was shouting about rent at about 11:15 p.m. and then a door slammed. The neighbor didn't see anyone come or go.\""), .direct("What did the lab say about the blood on the shirt?", "\"It was {V}'s blood, and {D}'s DNA was found inside the collar. The blood was fresh enough that it fit the time of the death.\""), .cross("The shirt could have been old, couldn't it?", "\"The blood was fresh, according to the lab. I do not believe it was old.\""), .cross("{D} lived in that apartment, didn't {D.he}?", "\"Yes. {D}'s DNA being on {D}'s own clothing is not by itself surprising.\""), .cross("Was the rent argument unusual between the roommates?", "\"I was told it was a recurring topic. I have no evidence that it had turned violent before.\""), .cross("Did you recover the knife?", "\"No. We searched the apartment, the dumpster, and the hallway and never found the weapon.\""), .cross("Does the camera show anything in {D}'s hands besides a bag?", "\"No. {D} holds a duffel and walks toward the stairs, and I can't tell what's in it.\"")],
        defenseRole: "Defendant's brother",
        defenseExam: [.direct("Did {D} call you that night?", "\"Yes, at around midnight. The call woke me up.\""), .direct("What did {D} say?", "\"{D} told me that {V} was dead. {D} was upset and shaking, and I could hear it.\""), .direct("What did you tell {D} to do?", "\"I told {D} to call 911. I do not know if that is what happened.\""), .direct("How are you related to {D}?", "\"I'm {D}'s sibling. We talk on the phone most days and I know {D}'s habits well.\""), .direct("What time did {D} call that night, and what was {D}'s state?", "\"A little after midnight. {D} was crying and could barely get the words out.\""), .direct("What did you do after the call?", "\"I told {D} to call 911 and I stayed on the line until {D} did. I drove over as soon as I could.\""), .cross("Did {D} call 911 first?", "\"I do not know. {D} called me before I knew about any 911 call.\""), .cross("How did {D} sound?", "\"Scared. It did not sound planned. But I cannot say what was in {D}'s mind.\""), .cross("Are you related to {D}?", "\"Yes. I know that matters. I am telling you what I heard.\""), .cross("Did {D} mention a fight before the call?", "\"Only that there had been an argument earlier about rent. {D} didn't say it was a physical fight.\""), .cross("Had {D} ever been violent with {V}?", "\"Not that I know of. {D} has a temper but it has never come to blows.\"")],
        theory: ("{D} stabbed {V} and fled.", "A roommate who found a body."),
        allocution: "\"I will never forgive myself.\"",
        truths: ("{DL}'s call to a brother came before any 911 call.", "The shirt in the dumpster was not {DL}'s size."),
        defendant: [.direct("Did you kill {V}?", "\"No. I did not hurt {V.him}. I left before the fight and I came back to find {V.him} dead.\""), .direct("Why did you leave with a bag at 11:40?", "\"I was leaving to stay somewhere else for a night. We had been arguing about rent.\""), .direct("What about the shirt in the dumpster?", "\"It was my shirt from earlier. I threw it away because it was dirty, and I did not know it had blood on it.\""), .direct("Tell us about your relationship with {V}.", "\"We were roommates for two years. We split rent, got along most of the time, and argued about money sometimes.\""), .direct("What happened at 11:15 that night?", "\"We argued about rent. I was angry and packed a bag to stay with a friend for a few days, and I left before it got any worse.\""), .direct("What did you find when you came back?", "\"The door was open and {V} was on the floor. I knelt down and saw there was nothing I could do, and I called a family member before dialing 911.\""), .cross("You left at 11:40, right after the shouting about rent, didn't you?", "\"I left before the fight, and I came back. I did not kill anyone.\""), .cross("Your DNA was inside the collar of a bloody shirt. How do you explain it?", "\"It was my shirt. I wore it before, and I tossed it. I do not know how it got that blood on it.\""), .cross("Why call your relative before 911?", "\"I panicked. I did not know what to do, and I called someone I trust.\""), .cross("You called a relative before you called 911. Why?", "\"I was in shock. I didn't know what to do and I needed to hear someone's voice.\""), .cross("Your DNA is on a bloody shirt in a dumpster. Why would you throw it out?", "\"It was my shirt and I'd worn it earlier. I threw it out because I panicked when I saw the blood, and I know that looks terrible.\"")],
        openings: ("{V} was found stabbed to death in a shared apartment after a neighbor heard shouting about rent. A hallway camera shows {D}, the roommate, leaving with a bag, and a bloody shirt with {D}'s DNA was in a dumpster.", "The defense evidence will establish that {D} left before any fight, came back to find {V} dead, and called for help. A shirt in a dumpster and a bag do not prove a killing."),
        closings: ("A fight about rent, a roommate leaving with a bag at 11:40, and a bloody shirt in the dumpster with {D}'s DNA inside the collar. These facts point one way.", "{D} lived in that apartment, so {D}'s things were there. {D} left before the fight and called for help on coming back. The State has suspicion, but it has not proved murder."),
        timeline: [(0, "11:15 p.m.: the neighbor hears shouting."), (0, "11:40 p.m.: {DL} leaves with a bag."), (1, "12 a.m.: {DL} calls a brother."), (1, "The shirt is found in a dumpster.")],
        identified: "A hallway camera and DNA.",
        aggravating: ["The offense involved a weapon"],
        mood: .wantsConviction,
        impact: "He was kind to everyone.",
        doctrines: ["burdenOfProof", "lesserIncluded"],
        genders: ["D": .male, "V": .male])

    static let ambushAtHome = SmallCases.make(
        key: "story.ambushAtHome",
        category: .violent,
        headlines: ["Man Shot at Through Window of Ex's House", "Shell Casings Matched to Pistol in Defendant's Car"],
        law: "attemptedMurder1",
