        state: [E(.physical, 3, "Pistol", "A pistol matching five casings, found in {D}'s car.", .search), E(.digital, 3, "Threat Texts", "Weeks of threats from {D}'s phone."), E(.forensic, 2, "Medical Records", "A graze wound to the shoulder.")],
        defense: [E(.statement, 1, "Bar", "{DL} says {D.he} was at a bar."), E(.statement, 2, "Bartender", "A bartender recalls {D} until about 10:45.")],
        role: "Sheriff's detective",
        exam: [.direct("What was reported on {DATE}?", "\"At 11:30 p.m., five shots came through the front window of {V}'s home. One bullet grazed {V}'s shoulder.\""), .direct("What did {V} tell you?", "\"{V} named {D}, {V.his} ex, who had been sending threats for about thirty days. {V} was certain it was {D}.\""), .direct("What did the threat texts say?", "\"Weeks of messages from {D}'s phone that said {V} would regret the breakup. They became more frequent as the date approached.\""), .direct("What did you recover at the scene?", "\"Five casings from the street and bullet holes through the window. The bullet that grazed {V} was embedded in a wall.\""), .direct("What was found in {D}'s car?", "\"A pistol that matched the casings. It was found the day after the shooting.\""), .direct("What did {D} say?", "\"{D} said the pistol had been sold earlier and that {D.he} was at a bar when the shots were fired.\""), .cross("Isn't it true no one saw the shooter?", "\"Correct. {V} heard the shots and dropped to the floor. {V} didn't see who fired them.\""), .cross("Did {D} say who bought the pistol?", "\"{D} said it was sold but couldn't name the buyer. I haven't been able to find a record of the sale.\""), .cross("How far is the bar from {V}'s home?", "\"About twenty minutes by car. {D} would have had time to get there after leaving.\""), .cross("Did the bartender say when {D} left?", "\"The bartender recalled {D} until about 10:45. I don't have a record of the exact minute.\""), .cross("Were fingerprints on the pistol?", "\"Not that I could use. The pistol was handled, and the lab found a partial print I couldn't match.\"")],
        defenseRole: "Bartender",
        defenseExam: [.direct("What do you do at the bar?", "\"I'm the bartender. I serve drinks, run tabs, and see the regulars most nights.\""), .direct("Did you see {D} on the night in question?", "\"Yes. {D} was at the bar for a couple of hours, sitting and talking, and I served {D} a few drinks.\""), .direct("When did {D} leave?", "\"Around 10:45, as far as I remember. {D} paid the tab and walked out, and that's the last I saw.\""), .direct("How was {D} acting?", "\"Quiet, a little down. {D} talked about a breakup and seemed more sad than angry.\""), .direct("Do you have any record of the time?", "\"The tab shows a closing time near 10:45. I don't have a camera at the bar.\""), .direct("Did {D} mention a pistol?", "\"No. I don't recall any talk about a gun that night or any other.\""), .cross("You can't say where {D} went after leaving?", "\"No. I only saw {D} walk out the door.\""), .cross("You didn't see {D} again that night?", "\"No. I stayed at the bar until closing, and {D} didn't come back.\""), .cross("Did {D} drink heavily?", "\"A few drinks over a couple of hours. I wouldn't say {D} was drunk, but I wasn't counting.\""), .cross("You've known {D} a long time as a customer?", "\"Yes, a few years. I like {D}, and I'm telling you only what I saw.\""), .cross("How far is the bar from {V}'s home?", "\"I couldn't say exactly. I think it's a twenty-minute drive, but I don't live over there.\"")],
        theory: ("{D} shot at an ex.", "A man at a bar."),
        allocution: "\"I'm sorry. I almost killed {V}.\"",
        truths: ("{DL}'s phone left the bar at 10:50 p.m.", "The pistol was reported sold, but no buyer was found."),
        defendant: [.direct("Where were you at 11:30 that night?", "\"At a bar, drinking and talking to the bartender. I stayed until about a quarter to eleven and then went home.\""), .direct("What about the pistol?", "\"I sold it earlier. I needed money, and I sold it to someone I met, and I don't know the person's name.\""), .direct("Did you send the texts to {V}?", "\"Yes, I did, and I'm ashamed of them. I was hurt and angry, and I said things I didn't mean.\""), .direct("Did you shoot at {V}'s house?", "\"No. I would never shoot at anyone. I was angry, not violent, and I would never put {V} in danger.\""), .direct("Why was there a pistol in your car then?", "\"It wasn't mine anymore, or so I thought. I don't know how it ended up there, and I can't explain it.\""), .direct("What did you do after the bar?", "\"I drove home and went to bed. I didn't go near {V}'s house.\""), .cross("You sent weeks of threats to {V}, didn't you?", "\"Yes. They were wrong. I regret them, but I never meant to act on them.\""), .cross("A pistol matching the casings was in your car?", "\"So the detective says. I can't explain it, and I'm still confused by it.\""), .cross("You can't name the person who bought the pistol?", "\"No. It was a quick deal, and I didn't write it down. I know it sounds weak.\""), .cross("Your phone left the bar at 10:50?", "\"I believe I left around then. I can't say the exact minute.\""), .cross("You had time to get to {V}'s home before 11:30?", "\"I suppose it's possible in terms of driving time. But I went home.\"")],
        openings: ("At 11:30 p.m. five shots tore through the front window of {V}'s home and one grazed {V}'s shoulder. {V} named {D}, an ex who had sent threats for thirty days, and a pistol matching the casings was found in {D}'s car.", "{D} says the pistol had been sold, and a bartender confirms {D} was at the bar until about 10:45. The defense says the State has an ugly set of texts, but nothing that puts {D} at that window."),
        closings: ("Weeks of threats, five casings that match a pistol in {D}'s car, and a victim who knows who was angry enough. {D} left the bar at 10:45 with time to reach {V}'s home.", "No one saw the shooter, the pistol was sold to someone {D} cannot name, and the bartender places {D} at the bar until 10:45. Angry texts are not the same as pulling a trigger."),
        timeline: [(-30, "The threats begin."), (0, "10:45 p.m.: {DL} leaves the bar."), (0, "11:30 p.m.: five shots."), (1, "The pistol is found.")],
